#[derive(Default)]
struct PipelineCompletionWake(Mutex<Option<WorkerWake>>);

impl PipelineCompletionWake {
    fn install(&self, wake: WorkerWake) -> Result<(), PipelineWakeInstallError> {
        let mut slot = self.0.lock();
        if slot.is_some() {
            return Err(PipelineWakeInstallError::AlreadyInstalled);
        }
        *slot = Some(wake);
        Ok(())
    }

    fn wake(&self) {
        let wake = self.0.lock().as_ref().cloned();
        if let Some(wake) = wake {
            wake.wake();
        }
    }
}

fn translate_render_pipeline_contract(
    contract: &RenderPipelineContract,
    pipeline_ref: u32,
) -> Result<TranslatedRenderPipeline, RenderTranslationDecline> {
    let descriptor = Arc::clone(&contract.descriptor);
    let vertex_air = crate::runtime::replacement_air::extract_air(&contract.vertex_library)
        .map_err(|reason| RenderTranslationDecline::VertexAirExtract {
            function_ref: descriptor.vertex_func_ref,
            reason,
        })?;
    let fragment_air = crate::runtime::replacement_air::extract_air(&contract.fragment_library)
        .map_err(|reason| RenderTranslationDecline::FragmentAirExtract {
            function_ref: descriptor.fragment_func_ref,
            reason,
        })?;
    let sample_count = descriptor.effective_raster_sample_count();
    let vertex_shader = reims_vgpu_vulkan::m2v_cache::translate_render_cached_reflected(
        vertex_air,
        reims_vgpu_vulkan::m2v_cache::RenderTranslationStage::Vertex,
        sample_count,
        pipeline_ref,
    )
    .map_err(|reason| RenderTranslationDecline::VertexTranslate {
        pipeline_ref,
        reason,
    })?;
    let vertex = reims_vgpu_vulkan::m2v_cache::prepare_render_shader(
        &vertex_shader,
        reims_vgpu_vulkan::m2v_cache::RenderTranslationStage::Vertex,
    );
    let fragment_shader = reims_vgpu_vulkan::m2v_cache::translate_render_cached_reflected(
        fragment_air,
        reims_vgpu_vulkan::m2v_cache::RenderTranslationStage::Fragment,
        sample_count,
        pipeline_ref,
    )
    .map_err(|reason| RenderTranslationDecline::FragmentTranslate {
        pipeline_ref,
        reason,
    })?;
    let fragment = reims_vgpu_vulkan::m2v_cache::prepare_render_shader(
        &fragment_shader,
        reims_vgpu_vulkan::m2v_cache::RenderTranslationStage::Fragment,
    );
    Ok(TranslatedRenderPipeline {
        semantic: ResolvedRenderPipeline {
            pipeline_lifetime: None,
            bind_plan: Arc::new(reims_vgpu_core::VertexBindPlan::build(&descriptor)),
            desc: descriptor,
            vertex,
            fragment,
        },
        vertex_shader: vertex_shader.variant(),
        fragment_shader: fragment_shader.variant(),
    })
}

struct ReplacementComputeTranslation {
    shader: Arc<reims_vgpu_vulkan::m2v_cache::CachedShader>,
    capabilities: Arc<
        HashMap<
            reims_vgpu_protocol::StorageImageFormat,
            reims_vgpu_vulkan::replacement_device_epoch::ReplacementStorageImageCapabilities,
        >,
    >,
}

impl std::fmt::Debug for ReplacementComputeTranslation {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("ReplacementComputeTranslation")
            .field("interface", &self.shader.interface)
            .finish_non_exhaustive()
    }
}

impl ComputeTranslation for ReplacementComputeTranslation {
    fn interface(&self) -> &reims_vgpu_core::ShaderInterface {
        &self.shader.interface
    }

    fn static_threadgroup_memory_length(&self) -> Option<u64> {
        self.shader.static_threadgroup_memory_length()
    }

    fn used_descriptor_bindings(&self) -> Arc<[u32]> {
        self.shader.variant().used_descriptor_bindings.clone()
    }

    fn buffer_extent(
        &self,
        metal_index: u32,
        workgroups: [u32; 3],
        local_size: [u32; 3],
    ) -> Option<u64> {
        reims_vgpu_vulkan::spirv_bind::reflected_compute_buffer_extent_interface(
            &self.shader.interface,
            metal_index,
            workgroups,
            local_size,
        )
    }

    fn storage_image_access(&self, binding: u32) -> Option<reims_vgpu_core::StorageImageAccess> {
        self.shader.storage_image_access(binding)
    }

    fn samplers(&self) -> Arc<[reims_vgpu_core::ReflectedSamplerDescriptor]> {
        self.shader.kernel_samplers()
    }

    fn prepare_program(
        &self,
        requests: &[(u32, reims_vgpu_protocol::StorageImageFormat)],
        samplers: &[reims_vgpu_core::SamplerResource],
        dispatch: reims_vgpu_core::ComputeProgramDispatchContract,
    ) -> Result<PreparedComputeProgram, crate::runtime::replacement_services::ComputeProgramDecline>
    {
        use crate::runtime::replacement_services::ComputeProgramDecline;
        let native = requests
            .iter()
            .map(|(binding, format)| {
                let metal_index = self
                    .shader
                    .interface
                    .bindings
                    .iter()
                    .find(|resource| {
                        resource.descriptor.map(|descriptor| descriptor.binding) == Some(*binding)
                            && matches!(
                                resource.kind,
                                reims_vgpu_core::ShaderResourceKind::StorageImage
                                    | reims_vgpu_core::ShaderResourceKind::TextureArray
                                    | reims_vgpu_core::ShaderResourceKind::EmbeddedArgBufferTexture
                            )
                    })
                    .map(|resource| resource.metal_index)
                    .ok_or_else(|| {
                        ComputeProgramDecline::Specialization(
                            reims_vgpu_vulkan::m2v_cache::M2vCacheDecline::RuntimeStorageImageSpecialize {
                                detail: format!(
                                    "no reflected storage image at descriptor binding {binding}"
                                ),
                            },
                        )
                    })?;
                let caps = self.capabilities.get(format).copied().ok_or_else(|| {
                    ComputeProgramDecline::Specialization(
                        reims_vgpu_vulkan::m2v_cache::M2vCacheDecline::RuntimeStorageImageSpecialize {
                            detail: format!("storage image capability absent for {format:?}"),
                        },
                    )
                })?;
                Ok(reims_vgpu_vulkan::m2v_cache::RuntimeStorageImageRequest {
                    binding: *binding,
                    metal_index,
                    format: *format,
                    storage_image: caps.storage_image,
                    storage_image_atomic: caps.storage_image_atomic,
                    read_without_format: caps.read_without_format,
                    write_without_format: caps.write_without_format,
                })
            })
            .collect::<Result<Vec<_>, _>>()?;
        let native_dispatch = match dispatch {
            reims_vgpu_core::ComputeProgramDispatchContract::DynamicThreads => {
                reims_vgpu_vulkan::m2v_cache::KernelDispatchContract::DynamicThreads
            }
            reims_vgpu_core::ComputeProgramDispatchContract::Workgroups => {
                reims_vgpu_vulkan::m2v_cache::KernelDispatchContract::Workgroups
            }
        };
        let prepared = self
            .shader
            .prepare_kernel_for_dispatch(&native, samplers, native_dispatch)
            .map_err(ComputeProgramDecline::Specialization)?;
        Ok(PreparedComputeProgram {
            stage: reims_vgpu_vulkan::m2v_cache::prepared_stage(&prepared.variant),
            dispatch,
            _native_lifetime: Box::new(prepared),
        })
    }
}

fn translate_compute_pipeline_contract(
    contract: &LoadedComputePipeline,
    local_size: [u32; 3],
    pipeline_ref: u32,
    capabilities: Arc<
        HashMap<
            reims_vgpu_protocol::StorageImageFormat,
            reims_vgpu_vulkan::replacement_device_epoch::ReplacementStorageImageCapabilities,
        >,
    >,
) -> Result<Arc<dyn ComputeTranslation>, ComputeTranslationDecline> {
    let air = crate::runtime::replacement_air::extract_air(&contract.kernel_mtlb)
        .map_err(ComputeTranslationDecline::Air)?;
    let shader = reims_vgpu_vulkan::m2v_cache::translate_cached_kernel_reflected(
        air,
        local_size,
        pipeline_ref,
    )
    .map_err(ComputeTranslationDecline::Translation)?;
    Ok(Arc::new(ReplacementComputeTranslation {
        shader,
        capabilities,
    }))
}

