struct ReplacementGenerationExecutionOwners<Semantic> {
    generation: reims_vgpu_core::SessionGeneration,
    runtime: reims_vgpu_core::TransactionRuntime<Semantic>,
    namespaces: reims_vgpu_core::TaskNamespaceOwner,
    samplers: reims_vgpu_core::ObjectStateOwner<SamplerObject, SamplerDescriptor>,
    depth_stencil: reims_vgpu_core::ObjectStateOwner<DepthStencilObject, DepthStencilDescriptor>,
    functions: reims_vgpu_core::ObjectStateOwner<FunctionObject, LoadedFunction>,
    rasterization_rate_maps: reims_vgpu_core::ObjectStateOwner<
        RasterizationRateMapObject,
        RasterizationRateMapDescriptor,
    >,
    indirect_descriptors: reims_vgpu_core::ObjectStateOwner<
        IndirectCommandBufferObject,
        IndirectCommandBufferDescriptor,
    >,
    indirect_command_memory:
        BTreeMap<ResourceId<IndirectCommandBufferObject>, reims_vgpu_protocol::IcbCommandMemory>,
    indirect: reims_vgpu_core::IndirectCommandSlotOwner<
        ResolvedIndirectCommandSlot<ResolvedRenderDispatch, ResolvedComputeDispatch>,
    >,
}

fn empty_generation_execution_owners<Semantic: Clone>(
    generation: reims_vgpu_core::SessionGeneration,
) -> ReplacementGenerationExecutionOwners<Semantic> {
    ReplacementGenerationExecutionOwners {
        runtime: reims_vgpu_core::TransactionRuntime::new(generation.clone()),
        generation,
        namespaces: reims_vgpu_core::TaskNamespaceOwner::default(),
        samplers: reims_vgpu_core::ObjectStateOwner::default(),
        depth_stencil: reims_vgpu_core::ObjectStateOwner::default(),
        functions: reims_vgpu_core::ObjectStateOwner::default(),
        rasterization_rate_maps: reims_vgpu_core::ObjectStateOwner::default(),
        indirect_descriptors: reims_vgpu_core::ObjectStateOwner::default(),
        indirect_command_memory: BTreeMap::new(),
        indirect: reims_vgpu_core::IndirectCommandSlotOwner::default(),
    }
}

struct ReplacementEpochExecutionOwners<Semantic> {
    native: reims_vgpu_core::DirectReplayNativeOwner<ResolvedReplayCompletion<Semantic>>,
    resources: reims_vgpu_core::ResourceLifecycleOwner<ReplacementNativeRepresentation>,
    recordings: ReplacementRecordingOwner,
    images: ReplacementImageStateOwner,
    recorded_execs: BTreeMap<TransactionId, ReplacementRecordedExec>,
    recorded_indirect_ranges:
        BTreeMap<TransactionId, ReplacementRecordedIndirectRangePhase<Semantic>>,
    recorded_guest_uploads: BTreeMap<TransactionId, ReplacementRecordedGuestUploadPhase<Semantic>>,
}

/// Canonical replay ownership split at the contract's two independent
/// lifetimes. Reset replaces only the active semantic generation. The native
/// timeline allocator, submitted completion facts, backing obligations, and
/// recording retirement remain owned by the healthy Vulkan incarnation.
pub(crate) struct ReplacementExecutionOwners<Semantic> {
    active: ReplacementGenerationExecutionOwners<Semantic>,
    retired: BTreeMap<SessionGenerationId, reims_vgpu_core::TransactionRuntime<Semantic>>,
    epoch: ReplacementEpochExecutionOwners<Semantic>,
}

