#[derive(Debug)]
pub(crate) struct ReplacementPreparedAdmittedExec<Completion> {
    admitted: CanonicalAdmittedExecTransaction<Completion>,
    indirect: CanonicalPreparedIndirectExecution<Completion>,
    semantic_proofs: reims_vgpu_core::AdmittedExpandedExecProofs<
        reims_vgpu_core::ResolvedInfoOperation,
        Completion,
    >,
    resource_proofs: reims_vgpu_core::AdmittedExpandedExecProofs<
        reims_vgpu_core::ResolvedInfoOperation,
        Completion,
    >,
    staged_indirect: CanonicalIndirectSlotOwner,
}

impl<Completion> ReplacementPreparedAdmittedExec<Completion> {
    pub const fn admitted(&self) -> &CanonicalAdmittedExecTransaction<Completion> {
        &self.admitted
    }

    pub const fn exec(&self) -> &CanonicalReplacementExecTransaction<Completion> {
        self.indirect.exec()
    }

    pub const fn origins(&self) -> &[reims_vgpu_core::ExpandedIndirectOperationOrigin] {
        self.indirect.origins()
    }

    pub const fn indirect_commands(
        &self,
    ) -> &reims_vgpu_core::AdmittedIndirectCommands<reims_vgpu_core::ResolvedIndirectCommand> {
        self.semantic_proofs.indirect_commands()
    }

    pub const fn info_queries_for_resource_preparation(
        &self,
    ) -> &reims_vgpu_core::AdmittedInfoQueries<reims_vgpu_core::ResolvedInfoOperation> {
        self.resource_proofs.info_queries()
    }

    pub const fn resource_states_for_preparation(
        &self,
    ) -> &reims_vgpu_core::AdmittedResourceStates {
        self.resource_proofs.resource_states()
    }
}

