pub(crate) enum ReplacementUnpreparedIndirectRangePhase<Completion> {
    Readback {
        admitted: CanonicalAdmittedExecTransaction<Completion>,
        indirect_commands:
            reims_vgpu_core::AdmittedIndirectCommands<reims_vgpu_core::ResolvedIndirectCommand>,
        pending: reims_vgpu_core::PendingIndirectRangeExecution<
            ResolvedRenderDispatch,
            ResolvedComputeDispatch,
            reims_vgpu_core::ResolvedInfoOperation,
            Completion,
        >,
        next_expanded_position: usize,
        head_reserved: bool,
    },
    Final {
        admitted: CanonicalAdmittedExecTransaction<Completion>,
        indirect_commands:
            reims_vgpu_core::AdmittedIndirectCommands<reims_vgpu_core::ResolvedIndirectCommand>,
        phase: reims_vgpu_core::IndirectRangeExecutionPhase<
            ResolvedRenderDispatch,
            ResolvedComputeDispatch,
            reims_vgpu_core::ResolvedInfoOperation,
            Completion,
        >,
        next_expanded_position: usize,
        head_reserved: bool,
    },
}

impl<Completion> ReplacementUnpreparedIndirectRangePhase<Completion> {
    fn phase(
        &self,
    ) -> &reims_vgpu_core::IndirectRangeExecutionPhase<
        ResolvedRenderDispatch,
        ResolvedComputeDispatch,
        reims_vgpu_core::ResolvedInfoOperation,
        Completion,
    > {
        match self {
            Self::Readback { pending, .. } => pending.phase(),
            Self::Final { phase, .. } => phase,
        }
    }

    fn admitted(&self) -> &CanonicalAdmittedExecTransaction<Completion> {
        match self {
            Self::Readback { admitted, .. } | Self::Final { admitted, .. } => admitted,
        }
    }
}

