impl<Semantic> PendingReplacementRecordedIndirectAuxiliary<Semantic> {
    fn try_complete(self) -> ReplacementRecordedIndirectAuxiliaryDriverPoll<Semantic> {
        let Self {
            pending,
            native,
            phase,
            resources,
            image_states,
        } = self;
        match pending.try_complete() {
            reims_vgpu_vulkan::replacement_queue::PreparedReplacementAuxiliaryQueueSubmitPoll::Pending(pending) => {
                ReplacementRecordedIndirectAuxiliaryDriverPoll::Pending(Self {
                    pending,
                    native,
                    phase,
                    resources,
                    image_states,
                })
            }
            reims_vgpu_vulkan::replacement_queue::PreparedReplacementAuxiliaryQueueSubmitPoll::DriverAccepted(submission) => {
                ReplacementRecordedIndirectAuxiliaryDriverPoll::DriverAccepted(
                    DriverAcceptedReplacementRecordedIndirectAuxiliary {
                        native,
                        submission,
                        phase,
                        resources,
                        image_states,
                    },
                )
            }
            reims_vgpu_vulkan::replacement_queue::PreparedReplacementAuxiliaryQueueSubmitPoll::DriverRefused { reason, submission } => {
                ReplacementRecordedIndirectAuxiliaryDriverPoll::DriverRefused {
                    reason,
                    prepared: ReplacementPreparedRecordedIndirectAuxiliary {
                        native,
                        submission,
                        phase,
                        resources,
                        image_states,
                    },
                }
            }
        }
    }
}

#[derive(Debug)]
pub(crate) struct ReplacementIndirectRangeRecordingCompletionFailure<Completion> {
    pub failure: Box<ReplacementAdmittedRecordingDispatchFailure<Completion>>,
    pub phase: ReplacementUnpreparedIndirectRangePhase<Completion>,
}

impl<Completion> PendingReplacementIndirectRangeRecording<Completion> {
    #[cfg(test)]
    pub fn wait(
        self,
    ) -> Result<
        ReplacementRecordedIndirectRangePhase<Completion>,
        Box<ReplacementIndirectRangeRecordingCompletionFailure<Completion>>,
    > {
        match self.pending.wait() {
            Ok(recorded) => Ok(ReplacementRecordedIndirectRangePhase {
                recorded,
                phase: self.phase,
            }),
            Err(failure) => Err(Box::new(
                ReplacementIndirectRangeRecordingCompletionFailure {
                    failure,
                    phase: self.phase,
                },
            )),
        }
    }
}

#[derive(Debug)]
pub(crate) enum ReplacementAdmittedRecordingError<Completion> {
    RecordingNotReady(TransactionId),
    MissingRecordingPlan(TransactionId),
    Assignment(reims_vgpu_core::DirectReplayError),
    MissingHazardPlan(TransactionId),
    BarrierPlan(reims_vgpu_vulkan::replacement_barriers::BarrierPlanError),
    BarrierResolution(reims_vgpu_vulkan::replacement_barrier_record::BarrierRecordError),
    IndirectAdmission(reims_vgpu_core::IndirectCommandAdmissionError),
    IndirectPreparation(Box<reims_vgpu_core::IndirectExecutionPreparationFailure>),
    IndirectRangeContinuationRequired(TransactionId),
    Program(Box<CanonicalReplacementProgramFailure<Completion>>),
}

#[derive(Debug)]
pub(crate) enum ReplacementPreparedAdmittedRecordingError<Completion> {
    RecordingNotReady(TransactionId),
    MissingRecordingPlan(TransactionId),
    Assignment(reims_vgpu_core::DirectReplayError),
    MissingHazardPlan(TransactionId),
    BarrierPlan(reims_vgpu_vulkan::replacement_barriers::BarrierPlanError),
    BarrierResolution(reims_vgpu_vulkan::replacement_barrier_record::BarrierRecordError),
    IndirectRangeContinuationRequired(TransactionId),
    Program(Box<CanonicalReplacementProgramFailure<Completion>>),
}

impl<Completion> ReplacementPreparedAdmittedRecordingError<Completion> {
    /// See [`ReplacementExecResourceTableError::is_terminal_refusal`].
    ///
    /// Recording is where a decoded view meets the native image that already
    /// exists, so it is the one place a refusal can be settled by two facts a
    /// retry cannot move.
    pub(crate) const fn is_terminal_refusal(&self) -> bool {
        match self {
            Self::Program(failure) => failure.reason.is_terminal_refusal(),
            Self::RecordingNotReady(_)
            | Self::MissingRecordingPlan(_)
            | Self::Assignment(_)
            | Self::MissingHazardPlan(_)
            | Self::BarrierPlan(_)
            | Self::BarrierResolution(_)
            | Self::IndirectRangeContinuationRequired(_) => false,
        }
    }
}

impl<Completion> ReplacementPreparedAdmittedRecordingError<Completion> {
    pub fn detail(&self) -> String {
        match self {
            Self::RecordingNotReady(transaction) => {
                format!("RecordingNotReady({transaction:?})")
            }
            Self::MissingRecordingPlan(transaction) => {
                format!("MissingRecordingPlan({transaction:?})")
            }
            Self::Assignment(reason) => format!("Assignment({reason:?})"),
            Self::MissingHazardPlan(transaction) => {
                format!("MissingHazardPlan({transaction:?})")
            }
            Self::BarrierPlan(reason) => format!("BarrierPlan({reason:?})"),
            Self::BarrierResolution(reason) => format!("BarrierResolution({reason:?})"),
            Self::IndirectRangeContinuationRequired(transaction) => {
                format!("IndirectRangeContinuationRequired({transaction:?})")
            }
            Self::Program(failure) => format!("Program({:?})", failure.reason),
        }
    }
}

