#[must_use = "replacement EXEC recording ownership must be polled to completion"]
pub(crate) struct PendingReplacementAdmittedRecording<Completion> {
    pending: reims_vgpu_vulkan::replacement_recording::PendingReplacementRecording<
        CanonicalReplacementOperation<Completion>,
    >,
    generation: SessionGenerationId,
    resources: PreparedReplacementExecResources,
    image_states: Option<reims_vgpu_vulkan::replacement_image_state::PreparedImageStateBatch>,
}

pub(crate) enum ReplacementAdmittedRecordingPoll<Completion> {
    Pending(PendingReplacementAdmittedRecording<Completion>),
    Completed(
        Result<
            ReplacementRecordedExec,
            Box<ReplacementAdmittedRecordingDispatchFailure<Completion>>,
        >,
    ),
}

pub(crate) enum ReplacementDirectRecordingProgress<Completion> {
    Pending(Box<PendingReplacementAdmittedRecording<Completion>>),
    Ready(Box<ReplacementQueueReadyExec>),
    Parked(TransactionId),
}

pub(crate) enum ReplacementDirectRecordingProgressFailure<Completion> {
    Recording(Box<ReplacementAdmittedRecordingDispatchFailure<Completion>>),
    Transition(Box<ReplacementRecordedExecTransitionFailure>),
    Queue(Box<ReplacementRecordedExecQueueFailure>),
}

impl<Completion> PendingReplacementAdmittedRecording<Completion> {
    pub fn transaction(&self) -> TransactionId {
        self.resources.transaction()
    }

    pub fn try_complete(self) -> ReplacementAdmittedRecordingPoll<Completion> {
        let Self {
            pending,
            generation,
            resources,
            image_states,
        } = self;
        match pending.try_complete() {
            reims_vgpu_vulkan::replacement_recording::ReplacementRecordingPoll::Pending(
                pending,
            ) => ReplacementAdmittedRecordingPoll::Pending(Self {
                pending,
                generation,
                resources,
                image_states,
            }),
            reims_vgpu_vulkan::replacement_recording::ReplacementRecordingPoll::Completed(
                result,
            ) => ReplacementAdmittedRecordingPoll::Completed(match result {
                Ok(recording) => Ok(ReplacementRecordedExec {
                    generation,
                    recording,
                    resources,
                    image_states,
                }),
                Err(reason) => Err(Box::new(ReplacementAdmittedRecordingDispatchFailure {
                    reason: ReplacementAdmittedRecordingDispatchError::Dispatch(reason),
                    generation,
                    resources,
                    image_states,
                })),
            }),
        }
    }

    #[cfg(test)]
    fn wait(
        self,
    ) -> Result<ReplacementRecordedExec, Box<ReplacementAdmittedRecordingDispatchFailure<Completion>>>
    {
        let Self {
            pending,
            generation,
            resources,
            image_states,
        } = self;
        match pending.wait() {
            Ok(recording) => Ok(ReplacementRecordedExec {
                generation,
                recording,
                resources,
                image_states,
            }),
            Err(reason) => Err(Box::new(ReplacementAdmittedRecordingDispatchFailure {
                reason: ReplacementAdmittedRecordingDispatchError::Dispatch(reason),
                generation,
                resources,
                image_states,
            })),
        }
    }
}

/// Composition-owned preparation of one immutable EXEC. The mutable resource
/// lifecycle borrow cannot escape this value, so every acquired reservation is
/// either joined to the complete EXEC envelope or withdrawn through `cancel`.
#[must_use = "replacement EXEC resource preparation must be finished or cancelled"]
pub(crate) struct ReplacementExecResourcePreparation<'a> {
    resources: &'a mut reims_vgpu_core::ResourceLifecycleOwner<ReplacementNativeRepresentation>,
    prepared: ReplacementExecResourceOwner,
}

#[derive(Debug)]
pub(crate) enum ReplacementResourceStatePreparationFailure {
    TransactionMismatch {
        admitted: reims_vgpu_core::AdmittedResourceStates,
    },
    PositionOccupied {
        position: usize,
        admitted: reims_vgpu_core::AdmittedResourceStates,
    },
    Preparation {
        reason: reims_vgpu_core::ResourceStatePreparationOwnerError,
        cancelled:
            reims_vgpu_core::CancelledResourceStatePreparation<ReplacementNativeRepresentation>,
    },
    HostIngress {
        reason: ReplacementHostIngressPreparationError,
        cancelled:
            reims_vgpu_core::CancelledResourceStatePreparation<ReplacementNativeRepresentation>,
    },
    Cancellation(Box<reims_vgpu_core::ResourceStatePreparationCancellationFailure>),
    Admission {
        reason: reims_vgpu_core::ExecResourcePreparationError,
        admitted: reims_vgpu_core::AdmittedResourceStates,
        cancelled: reims_vgpu_core::CancelledResourceStateBatch<ReplacementNativeRepresentation>,
    },
    BatchCancellation {
        admitted: reims_vgpu_core::AdmittedResourceStates,
        failure: Box<reims_vgpu_core::ResourceStateBatchCancellationFailure>,
    },
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) enum ReplacementHostIngressPreparationError {
    EndpointAbsent(reims_vgpu_protocol::BackingId),
    Copy {
        backing: reims_vgpu_protocol::BackingId,
        reason: reims_vgpu_vulkan::replacement_representation::ReplacementBufferAllocationError,
    },
    Publication(reims_vgpu_core::HostIngressBatchError),
}

impl ReplacementExecResourcePreparation<'_> {
    fn copy_host_ingresses(
        resources: &reims_vgpu_core::ResourceLifecycleOwner<ReplacementNativeRepresentation>,
        ingresses: &[reims_vgpu_core::HostIngressKey],
    ) -> Result<(), ReplacementHostIngressPreparationError> {
        let mut regions = BTreeMap::<_, Vec<_>>::new();
        for ingress in ingresses {
            regions
                .entry(ingress.backing)
                .or_default()
                .push(ingress.region);
        }
        for (backing, regions) in regions {
            let staging = resources
                .representation(backing, reims_vgpu_core::HOST_REPRESENTATION)
                .and_then(ReplacementNativeRepresentation::host_staging)
                .ok_or(ReplacementHostIngressPreparationError::EndpointAbsent(
                    backing,
                ))?;
            staging
                .write_guest_regions_before_recording(&regions)
                .map_err(|reason| ReplacementHostIngressPreparationError::Copy {
                    backing,
                    reason,
                })?;
        }
        Ok(())
    }

    pub fn prepare_content_synchronization(
        &mut self,
        requests: impl IntoIterator<Item = reims_vgpu_core::ContentSynchronizationRequest>,
    ) -> Result<(), reims_vgpu_core::ContentSynchronizationError> {
        let prepared = reims_vgpu_core::prepare_content_synchronization(
            self.resources,
            self.prepared.transaction(),
            requests,
        )?;
        if let Err(failure) = self.prepared.push_content_synchronization(prepared) {
            return match reims_vgpu_core::cancel_prepared_content_synchronization(
                self.resources,
                failure.input,
            ) {
                Ok(_) => {
                    unreachable!("one matching content synchronization batch is admitted once")
                }
                Err(reason) => Err(reims_vgpu_core::ContentSynchronizationError::Cancellation(
                    reason,
                )),
            };
        }
        Ok(())
    }

    pub fn prepare_buffer_blit(
        &mut self,
        submission: SubmissionId,
        position: usize,
        operation: reims_vgpu_core::ResolvedBlit,
    ) -> reims_vgpu_core::ExecResourcePreparationStepResult<
        Box<reims_vgpu_core::BufferBlitPreparationFailure>,
        reims_vgpu_core::ResolvedBlit,
    > {
        self.prepared
            .prepare_buffer_blit(self.resources, submission, position, operation)
    }

    pub fn prepare_image_blit(
        &mut self,
        submission: SubmissionId,
        position: usize,
        operation: reims_vgpu_core::ResolvedBlit,
    ) -> reims_vgpu_core::ExecResourcePreparationStepResult<
        Box<reims_vgpu_core::ImageBlitPreparationFailure>,
        reims_vgpu_core::ResolvedBlit,
    > {
        self.prepared
            .prepare_image_blit(self.resources, submission, position, operation)
    }

    pub fn prepare_compute(
        &mut self,
        submission: SubmissionId,
        position: usize,
        operation: ResolvedComputeDispatch,
        pipeline: ReadyPipelineLease<ComputePipelineObject, ReplacementComputePipelineVariant>,
    ) -> reims_vgpu_core::ComputeDispatchPreparationStepResult<ReplacementComputePipelineVariant>
    {
        self.prepared
            .prepare_compute(self.resources, submission, position, operation, pipeline)
    }

    pub fn prepare_render(
        &mut self,
        submission: SubmissionId,
        position: usize,
        operation: ResolvedRenderDispatch,
        pipeline: ReadyPipelineLease<RenderPipelineObject, ReplacementRenderPipelineVariant>,
    ) -> reims_vgpu_core::RenderDispatchPreparationStepResult<ReplacementRenderPipelineVariant>
    {
        self.prepared
            .prepare_render(self.resources, submission, position, operation, pipeline)
    }

    pub fn prepare_info(
        &mut self,
        submission: SubmissionId,
        evaluated: reims_vgpu_core::EvaluatedInfoQuery,
    ) -> reims_vgpu_core::ExecResourcePreparationStepResult<
        Box<reims_vgpu_core::InfoQueryPreparationFailure>,
        reims_vgpu_core::EvaluatedInfoQuery,
    > {
        self.prepared
            .prepare_info(self.resources, submission, evaluated)
    }

    pub fn prepare_indirect_range(
        &mut self,
        position: usize,
        operation: reims_vgpu_core::ResolvedIndirectCommand,
    ) -> reims_vgpu_core::ExecResourcePreparationStepResult<
        (
            reims_vgpu_core::IndirectRangeReadbackError,
            reims_vgpu_core::ResolvedIndirectCommand,
        ),
        reims_vgpu_core::ResolvedIndirectCommand,
    > {
        self.prepared
            .prepare_indirect_range(self.resources, position, operation)
    }

    pub fn prepare_resource_states(
        &mut self,
        admitted: reims_vgpu_core::AdmittedResourceStates,
        submission: SubmissionId,
        mut representations: impl FnMut(
            usize,
            reims_vgpu_protocol::BackingId,
        ) -> reims_vgpu_core::ValidityRepresentations,
    ) -> Result<(), Box<ReplacementResourceStatePreparationFailure>> {
        if admitted.transaction() != self.prepared.transaction() {
            return Err(Box::new(
                ReplacementResourceStatePreparationFailure::TransactionMismatch { admitted },
            ));
        }
        let positions = admitted
            .operations()
            .iter()
            .map(|(position, _)| *position)
            .collect::<Vec<_>>();
        if let Some(position) = self
            .prepared
            .first_occupied_position(positions.iter().copied())
        {
            return Err(Box::new(
                ReplacementResourceStatePreparationFailure::PositionOccupied { position, admitted },
            ));
        }

        let admitted_recovery = admitted.clone();
        let mut states = reims_vgpu_core::ResourceStatePreparationOwner::new(admitted);
        for position in positions {
            if let Err(reason) =
                states.prepare(self.resources, position, submission, &mut representations)
            {
                return match states.cancel(self.resources) {
                    Ok(cancelled) => Err(Box::new(
                        ReplacementResourceStatePreparationFailure::Preparation {
                            reason,
                            cancelled,
                        },
                    )),
                    Err(failure) => Err(Box::new(
                        ReplacementResourceStatePreparationFailure::Cancellation(failure),
                    )),
                };
            }
            let ingresses = states.host_ingresses();
            if !ingresses.is_empty() {
                let result = Self::copy_host_ingresses(self.resources, &ingresses).and_then(|()| {
                    states
                        .publish_host_ingresses_after_copy(self.resources)
                        .map(|_| ())
                        .map_err(ReplacementHostIngressPreparationError::Publication)
                });
                if let Err(reason) = result {
                    return match states.cancel(self.resources) {
                        Ok(cancelled) => Err(Box::new(
                            ReplacementResourceStatePreparationFailure::HostIngress {
                                reason,
                                cancelled,
                            },
                        )),
                        Err(failure) => Err(Box::new(
                            ReplacementResourceStatePreparationFailure::Cancellation(failure),
                        )),
                    };
                }
            }
        }
        let batch = match states.finish() {
            Ok(batch) => batch,
            Err(_) => unreachable!("every admitted resource-state position was prepared"),
        };
        if let Err(failure) = self.prepared.push_resource_states(batch) {
            let reason = failure.reason;
            return match reims_vgpu_core::cancel_prepared_resource_state_batch(
                self.resources,
                failure.input,
            ) {
                Ok(cancelled) => Err(Box::new(
                    ReplacementResourceStatePreparationFailure::Admission {
                        reason,
                        admitted: admitted_recovery,
                        cancelled,
                    },
                )),
                Err(failure) => Err(Box::new(
                    ReplacementResourceStatePreparationFailure::BatchCancellation {
                        admitted: admitted_recovery,
                        failure,
                    },
                )),
            };
        }
        Ok(())
    }

    pub fn prepare_host_ingress_uploads(
        &mut self,
    ) -> Result<Box<[reims_vgpu_core::TransferKey]>, ReplacementHostIngressPreparationError> {
        Self::copy_host_ingresses(self.resources, &self.prepared.host_ingresses())?;
        self.prepared
            .publish_host_ingresses_after_copy(self.resources)
            .map_err(ReplacementHostIngressPreparationError::Publication)
    }

    pub fn finish<Indirect, Completion>(
        self,
        exec: &reims_vgpu_core::ExecTransaction<
            reims_vgpu_core::ResolvedOperation<
                ResolvedRenderDispatch,
                ResolvedComputeDispatch,
                reims_vgpu_core::ResolvedInfoOperation,
                Indirect,
                Completion,
            >,
        >,
        operation_base: usize,
    ) -> reims_vgpu_core::ExecResourcePreparationResult<
        ResolvedComputeDispatch,
        ReplacementComputePipelineVariant,
        ResolvedRenderDispatch,
        ReplacementRenderPipelineVariant,
    >
    where
        Indirect: reims_vgpu_core::IndirectRangeResourceOperation,
    {
        self.prepared.assemble(exec, operation_base)
    }

    pub fn finish_at_positions<Indirect, Completion>(
        self,
        exec: &reims_vgpu_core::ExecTransaction<
            reims_vgpu_core::ResolvedOperation<
                ResolvedRenderDispatch,
                ResolvedComputeDispatch,
                reims_vgpu_core::ResolvedInfoOperation,
                Indirect,
                Completion,
            >,
        >,
        operation_positions: &[usize],
    ) -> reims_vgpu_core::ExecResourcePreparationResult<
        ResolvedComputeDispatch,
        ReplacementComputePipelineVariant,
        ResolvedRenderDispatch,
        ReplacementRenderPipelineVariant,
    >
    where
        Indirect: reims_vgpu_core::IndirectRangeResourceOperation,
    {
        self.prepared
            .assemble_at_positions(exec, operation_positions)
    }

    pub fn finish_at_origins<Indirect, Completion>(
        self,
        exec: &reims_vgpu_core::ExecTransaction<
            reims_vgpu_core::ResolvedOperation<
                ResolvedRenderDispatch,
                ResolvedComputeDispatch,
                reims_vgpu_core::ResolvedInfoOperation,
                Indirect,
                Completion,
            >,
        >,
        origins: &[reims_vgpu_core::ExpandedIndirectOperationOrigin],
    ) -> reims_vgpu_core::ExecResourcePreparationResult<
        ResolvedComputeDispatch,
        ReplacementComputePipelineVariant,
        ResolvedRenderDispatch,
        ReplacementRenderPipelineVariant,
    >
    where
        Indirect: reims_vgpu_core::IndirectRangeResourceOperation,
    {
        self.prepared.assemble_at_origins(exec, origins)
    }

    pub fn cancel(
        self,
    ) -> reims_vgpu_core::ExecResourceCancellationResult<
        ReplacementNativeRepresentation,
        ResolvedComputeDispatch,
        ReplacementComputePipelineVariant,
        ResolvedRenderDispatch,
        ReplacementRenderPipelineVariant,
    > {
        self.prepared.cancel(self.resources)
    }
}

