#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) enum ReplacementRepresentationConstructionError {
    ResourceAbsent(ResourceId<reims_vgpu_protocol::ResourceObject>),
    DescriptorAbsent(ResourceId<reims_vgpu_protocol::ResourceObject>),
    TextureDeclarationAbsent(ResourceId<reims_vgpu_protocol::ResourceObject>),
    TextureView(reims_vgpu_core::TextureViewResolveError),
    MapperPlane(reims_vgpu_core::MapperTexturePlaneError),
    StorageAbsent(ResourceId<reims_vgpu_protocol::ResourceObject>),
    UnsupportedDescriptor(reims_vgpu_protocol::ObjectKind),
    RepresentationPlan(reims_vgpu_core::RepresentationRefusal),
    RouteHasNoOwnedWorkingRepresentation(reims_vgpu_core::RepresentationRoute),
    TransferEndpointAbsent(reims_vgpu_core::RepresentationRoute),
    BufferAllocation(
        reims_vgpu_vulkan::replacement_representation::ReplacementBufferAllocationError,
    ),
    GuestBufferImport(
        reims_vgpu_vulkan::replacement_device_epoch::ReplacementGuestBufferImportError,
    ),
    GuestBufferLengthMismatch {
        expected: u64,
        actual: u64,
    },
    GuestTextureLengthMismatch {
        expected: u64,
        actual: u64,
    },
    RegisteredSurfacePlaneLayout(reims_vgpu_protocol::SurfacePlaneLayoutError),
    GuestWindow(reims_vgpu_memory::GuestWindowError),
    TextureAllocation(
        reims_vgpu_vulkan::replacement_representation::ReplacementTextureAllocationError,
    ),
    TextureEndpoint(reims_vgpu_vulkan::replacement_representation::ReplacementTextureEndpointError),
    ShaderViewInstall(
        reims_vgpu_vulkan::replacement_representation::ReplacementShaderViewInstallError,
    ),
    Lifecycle(reims_vgpu_core::ManagedBackingError),
}

impl ReplacementRepresentationConstructionError {
    /// Whether re-offering this construction could ever answer differently.
    ///
    /// The ingress path re-offers a refused packet on every tick, which is
    /// right for a state that has not arrived: a resource, descriptor or
    /// storage the guest is about to create reaches this device on another
    /// channel, and the next attempt then lands. It is wrong for a case this
    /// backend has declared it does not build. That question has no pending
    /// state behind it, so the same answer comes back forever and the packet
    /// never leaves the head of its channel.
    ///
    /// Measured on a macos-13 desktop: one construction this backend did not
    /// build was re-offered about four hundred times a second for a whole
    /// boot. Every pipeline owner read zero throughout, so the device looked
    /// idle and healthy while its compositor channel was stopped and nothing
    /// after that packet ever ran.
    ///
    /// Only the arms this backend genuinely declines are named here.
    /// Everything else keeps the retry, because a wrong `true` throws guest
    /// work away and a wrong `false` costs only what today already costs.
    pub const fn is_unimplemented_case(&self) -> bool {
        match self {
            // A descriptor kind or a route this backend does not build. No
            // later packet turns one of these into a case it does build.
            Self::UnsupportedDescriptor(_) | Self::RouteHasNoOwnedWorkingRepresentation(_) => true,
            // A resource, descriptor, declaration or storage that has not
            // arrived yet, an allocation or import that can succeed on a later
            // attempt, and every refusal whose input this device does not own.
            Self::ResourceAbsent(_)
            | Self::DescriptorAbsent(_)
            | Self::TextureDeclarationAbsent(_)
            | Self::TextureView(_)
            | Self::MapperPlane(_)
            | Self::StorageAbsent(_)
            | Self::RepresentationPlan(_)
            | Self::TransferEndpointAbsent(_)
            | Self::BufferAllocation(_)
            | Self::GuestBufferImport(_)
            | Self::GuestBufferLengthMismatch { .. }
            | Self::GuestTextureLengthMismatch { .. }
            | Self::RegisteredSurfacePlaneLayout(_)
            | Self::GuestWindow(_)
            | Self::TextureAllocation(_)
            | Self::TextureEndpoint(_)
            | Self::ShaderViewInstall(_)
            | Self::Lifecycle(_) => false,
        }
    }
}

impl<Semantic: Clone> ReplacementExecutionOwners<Semantic> {
    fn owned_working_memory(
        route: reims_vgpu_core::RepresentationRoute,
    ) -> Result<reims_vgpu_core::WorkingMemoryClass, ReplacementRepresentationConstructionError>
    {
        match route {
            reims_vgpu_core::RepresentationRoute::NativeWorking { memory } => Ok(memory),
            reims_vgpu_core::RepresentationRoute::HostVisibleWorking => {
                Ok(reims_vgpu_core::WorkingMemoryClass::HostVisible)
            }
            reims_vgpu_core::RepresentationRoute::ImportedGuestTransfer { working } => Ok(working),
            reims_vgpu_core::RepresentationRoute::HostStagingTransfer { working } => Ok(working),
            reims_vgpu_core::RepresentationRoute::RenderPassMemoryless
            | reims_vgpu_core::RepresentationRoute::DirectGuestAlias
            | reims_vgpu_core::RepresentationRoute::HostStagingEndpoint => Err(
                ReplacementRepresentationConstructionError::RouteHasNoOwnedWorkingRepresentation(
                    route,
                ),
            ),
        }
    }

    fn guest_transfer_route(
        storage_mode: reims_vgpu_protocol::StorageMode,
        topology: reims_vgpu_core::HostMemoryTopology,
        capabilities: reims_vgpu_core::RepresentationCapabilities,
    ) -> Result<reims_vgpu_core::RepresentationRoute, ReplacementRepresentationConstructionError>
    {
        let planned = reims_vgpu_core::plan_representation(storage_mode, topology, capabilities)
            .map_err(ReplacementRepresentationConstructionError::RepresentationPlan)?;
        let working = match planned {
            reims_vgpu_core::RepresentationRoute::NativeWorking { memory } => Some(memory),
            reims_vgpu_core::RepresentationRoute::HostVisibleWorking => {
                Some(reims_vgpu_core::WorkingMemoryClass::HostVisible)
            }
            reims_vgpu_core::RepresentationRoute::ImportedGuestTransfer { .. }
            | reims_vgpu_core::RepresentationRoute::HostStagingTransfer { .. } => None,
            _ => {
                return Err(
                    ReplacementRepresentationConstructionError::RouteHasNoOwnedWorkingRepresentation(
                        planned,
                    ),
                );
            }
        };
        Ok(working.map_or(planned, |working| {
            if capabilities.imported_transfer {
                reims_vgpu_core::RepresentationRoute::ImportedGuestTransfer { working }
            } else {
                reims_vgpu_core::RepresentationRoute::HostStagingTransfer { working }
            }
        }))
    }

    pub fn new(
        generation: reims_vgpu_core::SessionGeneration,
        epoch: VulkanDeviceEpochId,
        recording_workers: usize,
    ) -> Result<Self, reims_vgpu_core::DirectReplayError> {
        Ok(Self {
            active: empty_generation_execution_owners(generation),
            retired: BTreeMap::new(),
            epoch: ReplacementEpochExecutionOwners {
                native: reims_vgpu_core::DirectReplayNativeOwner::new(epoch, recording_workers)?,
                resources: reims_vgpu_core::ResourceLifecycleOwner::new(epoch),
                recordings: ReplacementRecordingOwner::new(epoch),
                images: ReplacementImageStateOwner::new(epoch),
                recorded_execs: BTreeMap::new(),
                recorded_indirect_ranges: BTreeMap::new(),
                recorded_guest_uploads: BTreeMap::new(),
            },
        })
    }

    fn exec_acceptance<'a>(
        &'a mut self,
        queues: &'a mut reims_vgpu_vulkan::replacement_epoch::ReplacementQueueEpoch,
    ) -> reims_vgpu_vulkan::replacement_exec_acceptance::ReplacementExecAcceptanceOwners<
        'a,
        Semantic,
        ReplacementNativeRepresentation,
    > {
        reims_vgpu_vulkan::replacement_exec_acceptance::ReplacementExecAcceptanceOwners {
            runtime: &mut self.active.runtime,
            native: &mut self.epoch.native,
            resources: &mut self.epoch.resources,
            recordings: &mut self.epoch.recordings,
            queues,
            images: &mut self.epoch.images,
        }
    }

    pub const fn runtime(&self) -> &reims_vgpu_core::TransactionRuntime<Semantic> {
        &self.active.runtime
    }

    /// The runtime whose submission order tracks `transaction`.
    ///
    /// [`Self::runtime`] is the *active* generation's, and an exec is not
    /// active-scoped: a transaction admitted before a generation change has its
    /// order in `retired`, and the queue paths commit staged work back into the
    /// exec's own generation rather than into `active`. Asking `active` about
    /// such a transaction does not fail, it answers about a domain the
    /// transaction is not in -- which is how two attempts at an ordering rule
    /// came to report an issued head the census showed as submitted.
    ///
    /// A transaction's order lives in exactly one owner, so selecting by that
    /// removes the question rather than answering it: there is no generation to
    /// supply and none for a caller to get wrong.
    pub fn runtime_owning_submission_order(
        &self,
        transaction: TransactionId,
    ) -> Option<&reims_vgpu_core::TransactionRuntime<Semantic>> {
        if self.active.runtime.tracks_submission_order(transaction) {
            return Some(&self.active.runtime);
        }
        self.retired
            .values()
            .find(|runtime| runtime.tracks_submission_order(transaction))
    }

    pub fn runtime_mut(&mut self) -> &mut reims_vgpu_core::TransactionRuntime<Semantic> {
        &mut self.active.runtime
    }

    pub const fn resources(
        &self,
    ) -> &reims_vgpu_core::ResourceLifecycleOwner<ReplacementNativeRepresentation> {
        &self.epoch.resources
    }

    pub fn resources_mut(
        &mut self,
    ) -> &mut reims_vgpu_core::ResourceLifecycleOwner<ReplacementNativeRepresentation> {
        &mut self.epoch.resources
    }

    pub fn begin_exec_resource_preparation(
        &mut self,
        transaction: TransactionId,
    ) -> ReplacementExecResourcePreparation<'_> {
        ReplacementExecResourcePreparation {
            resources: &mut self.epoch.resources,
            prepared: ReplacementExecResourceOwner::new(transaction),
        }
    }

    /// Bind the canonical prepared-resource envelope to every native
    /// operation sidecar under the exact Vulkan epoch's active gate. Packet
    /// ingress cannot supply independent handle tables or an indirect staging
    /// allocator through this composition seam.
    fn attach_recording_representation_leases<Operation: Clone>(
        &self,
        request: reims_vgpu_vulkan::replacement_recording::ReplacementRecordingRequest<Operation>,
    ) -> Result<
        reims_vgpu_vulkan::replacement_recording::ReplacementRecordingRequest<Operation>,
        Box<
            reims_vgpu_vulkan::replacement_exec_recording::ReplacementExecProgramFailure<Operation>,
        >,
    > {
        use reims_vgpu_vulkan::replacement_exec_recording::{
            ReplacementExecProgramError, ReplacementExecProgramFailure,
        };
        let failure =
            |reason,
             request: reims_vgpu_vulkan::replacement_recording::ReplacementRecordingRequest<
                Operation,
            >| {
                Box::new(ReplacementExecProgramFailure {
                    reason,
                    input: reims_vgpu_vulkan::replacement_recording::ReplacementRecordingInput {
                        transaction: request.transaction,
                        worker: request.worker,
                        queue_family: request.queue_family,
                        exec: request.exec,
                        barriers: request.barriers,
                    },
                })
            };
        // The transaction's accepted uses are not the set of native objects a
        // recording names: a content-state transfer resolves both the source
        // and the destination representation of one backing, and the source is
        // the one being retired. Every native representation of a declared
        // backing is leased, so no raw handle the recording can hold outlives
        // the object it names.
        let accepted = self
            .epoch
            .resources
            .accepted_representations(request.transaction, request.backings())
            .map_err(|reason| {
                failure(
                    ReplacementExecProgramError::RepresentationUses(reason),
                    request.clone(),
                )
            })?;
        let mut leases = Vec::with_capacity(accepted.len());
        for &backing in request.backings() {
            for census in self.epoch.resources.representation_census(backing) {
                if !census.has_native {
                    continue;
                }
                let Some(native) = self
                    .epoch
                    .resources
                    .representation(backing, census.representation)
                else {
                    return Err(failure(
                        ReplacementExecProgramError::RepresentationNativeAbsent {
                            backing,
                            representation: census.representation,
                        },
                        request,
                    ));
                };
                leases.push(native.lease(backing, census.representation));
            }
        }
        for accepted in accepted.iter().copied() {
            if !leases.iter().any(|lease: &reims_vgpu_vulkan::replacement_representation::ReplacementNativeRepresentationLease| {
                lease.backing == accepted.backing && lease.representation == accepted.representation
            }) {
                return Err(failure(
                    ReplacementExecProgramError::RepresentationNativeAbsent {
                        backing: accepted.backing,
                        representation: accepted.representation,
                    },
                    request,
                ));
            }
        }
        request
            .attach_representation_leases(leases.into_boxed_slice())
            .map_err(|lease_failure| {
                failure(
                    ReplacementExecProgramError::RepresentationLeases(lease_failure.reason),
                    *lease_failure.request,
                )
            })
    }

    fn resolve_recording_request<Completion: Clone + PartialEq>(
        &self,
        device: &ReplacementDeviceEpoch,
        input: reims_vgpu_vulkan::replacement_recording::ReplacementRecordingInput<
            reims_vgpu_vulkan::replacement_exec_recording::CanonicalReplacementOperation<
                Completion,
            >,
        >,
        resources: &reims_vgpu_core::PreparedExecResources<
            ResolvedComputeDispatch,
            ReplacementComputePipelineVariant,
            ResolvedRenderDispatch,
            ReplacementRenderPipelineVariant,
        >,
        image_states: Option<&reims_vgpu_vulkan::replacement_image_state::PreparedImageStateBatch>,
        semantics: reims_vgpu_vulkan::replacement_exec_recording::ReplacementExecSemanticAdmissions<
            '_,
            Completion,
        >,
    ) -> Result<
        reims_vgpu_vulkan::replacement_recording::ReplacementRecordingRequest<
            reims_vgpu_vulkan::replacement_exec_recording::CanonicalReplacementOperation<
                Completion,
            >,
        >,
        Box<
            reims_vgpu_vulkan::replacement_exec_recording::ReplacementExecProgramFailure<
                reims_vgpu_vulkan::replacement_exec_recording::CanonicalReplacementOperation<
                    Completion,
                >,
            >,
        >,
    > {
        let resolver = device.execution_resolver(&self.epoch.resources, &self.epoch.images);
        let request = device.resolve_prepared_exec_recording(
            input,
            resources,
            image_states,
            semantics,
            &resolver,
        )?;
        self.attach_recording_representation_leases(request)
    }

    fn resolve_continuation_recording_request<Completion: Clone + PartialEq>(
        &self,
        device: &ReplacementDeviceEpoch,
        input: reims_vgpu_vulkan::replacement_recording::ReplacementRecordingInput<
            reims_vgpu_vulkan::replacement_exec_recording::CanonicalReplacementOperation<
                Completion,
            >,
        >,
        resources: &reims_vgpu_core::PreparedExecResources<
            ResolvedComputeDispatch,
            ReplacementComputePipelineVariant,
            ResolvedRenderDispatch,
            ReplacementRenderPipelineVariant,
        >,
        image_states: Option<&reims_vgpu_vulkan::replacement_image_state::PreparedImageStateBatch>,
        semantics: reims_vgpu_vulkan::replacement_exec_recording::ReplacementExecSemanticAdmissions<
            '_,
            Completion,
        >,
        operation_origins: &[reims_vgpu_core::ExpandedIndirectOperationOrigin],
    ) -> Result<
        reims_vgpu_vulkan::replacement_recording::ReplacementRecordingRequest<
            reims_vgpu_vulkan::replacement_exec_recording::CanonicalReplacementOperation<
                Completion,
            >,
        >,
        Box<
            reims_vgpu_vulkan::replacement_exec_recording::ReplacementExecProgramFailure<
                reims_vgpu_vulkan::replacement_exec_recording::CanonicalReplacementOperation<
                    Completion,
                >,
            >,
        >,
    > {
        let resolver = device.execution_resolver(&self.epoch.resources, &self.epoch.images);
        let request = device.resolve_prepared_exec_continuation_recording(
            input,
            resources,
            image_states,
            semantics,
            &resolver,
            operation_origins,
        )?;
        self.attach_recording_representation_leases(request)
    }

    pub fn indirect_mut(
        &mut self,
    ) -> &mut reims_vgpu_core::IndirectCommandSlotOwner<
        ResolvedIndirectCommandSlot<ResolvedRenderDispatch, ResolvedComputeDispatch>,
    > {
        &mut self.active.indirect
    }

    pub fn indirect(
        &self,
    ) -> &reims_vgpu_core::IndirectCommandSlotOwner<
        ResolvedIndirectCommandSlot<ResolvedRenderDispatch, ResolvedComputeDispatch>,
    > {
        &self.active.indirect
    }

    /// Close current semantic admission and install its successor without
    /// replacing any Vulkan-epoch owner. A runtime with live accepted work is
    /// retained so timeline facts can still reach its exact publication
    /// domain after reset.
    pub fn reset_generation(
        &mut self,
        generation: reims_vgpu_core::SessionGeneration,
    ) -> Result<SessionGenerationId, ReplacementExecutionResetError> {
        let next = generation.id();
        if next == self.active.generation.id() || self.retired.contains_key(&next) {
            return Err(ReplacementExecutionResetError::DuplicateGeneration(next));
        }
        let successor = self.active.runtime.successor_generation(generation.clone());
        let prior = std::mem::replace(
            &mut self.active,
            ReplacementGenerationExecutionOwners {
                runtime: successor,
                ..empty_generation_execution_owners(generation)
            },
        );
        let closed = prior.generation.id();
        prior.generation.close();
        if prior.runtime.live_transactions() != 0 {
            self.retired.insert(closed, prior.runtime);
        }
        Ok(closed)
    }

    /// Terminate every old-generation execution owner after the platform has
    /// established a queue-idle reset boundary. Queue timeline allocation
    /// remains in `native`; all other epoch-local semantic/native ownership is
    /// rebuilt for the same Vulkan incarnation.
    pub fn platform_reset_epoch_owners(
        &mut self,
        epoch: VulkanDeviceEpochId,
    ) -> ReplacementPlatformResetAbandonment {
        let semantic_transactions = self
            .retired
            .values()
            .map(reims_vgpu_core::TransactionRuntime::live_transactions)
            .sum();
        let replay = self.epoch.native.platform_reset();
        let resources = std::mem::replace(
            &mut self.epoch.resources,
            reims_vgpu_core::ResourceLifecycleOwner::new(epoch),
        )
        .abandon();
        let recordings = std::mem::replace(
            &mut self.epoch.recordings,
            ReplacementRecordingOwner::new(epoch),
        )
        .abandon();
        self.epoch.images = ReplacementImageStateOwner::new(epoch);
        self.epoch.recorded_execs.clear();
        self.epoch.recorded_indirect_ranges.clear();
        self.epoch.recorded_guest_uploads.clear();
        self.retired.clear();
        ReplacementPlatformResetAbandonment {
            semantic_transactions,
            unsubmitted_transactions: replay.unsubmitted.len(),
            submitted_transactions: replay.submitted.len(),
            native_representations: resources.len(),
            native_recordings: recordings.len(),
        }
    }

    /// Abandon every semantic-generation and native-epoch owner after device
    /// loss. The current generation id is retained only as terminal metadata;
    /// no successor generation is opened.
    pub fn device_loss_epoch_owners(
        &mut self,
        epoch: VulkanDeviceEpochId,
    ) -> ReplacementPlatformResetAbandonment {
        let generation = self.active.generation.clone();
        let prior = std::mem::replace(
            &mut self.active,
            empty_generation_execution_owners(generation),
        );
        let semantic_transactions = prior.runtime.live_transactions()
            + self
                .retired
                .values()
                .map(reims_vgpu_core::TransactionRuntime::live_transactions)
                .sum::<usize>();
        let mut abandonment = self.platform_reset_epoch_owners(epoch);
        abandonment.semantic_transactions = semantic_transactions;
        abandonment
    }

    pub fn runtime_for_generation_mut(
        &mut self,
        generation: SessionGenerationId,
    ) -> Option<&mut reims_vgpu_core::TransactionRuntime<Semantic>> {
        if self.active.generation.id() == generation {
            Some(&mut self.active.runtime)
        } else {
            self.retired.get_mut(&generation)
        }
    }

    pub const fn native_mut(
        &mut self,
    ) -> &mut reims_vgpu_core::DirectReplayNativeOwner<ResolvedReplayCompletion<Semantic>> {
        &mut self.epoch.native
    }

    pub fn retired_generation_count(&self) -> usize {
        self.retired.len()
    }

    /// Construct and publish the working Vulkan buffer for one exact semantic
    /// resource generation. Buffer resources have no API usage restriction,
    /// so the native object carries every operation-class usage the replacement
    /// recorder may issue; placement alone follows the selected route.
    fn materialize_buffer(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
        route: reims_vgpu_core::RepresentationRoute,
    ) -> Result<reims_vgpu_protocol::RepresentationId, ReplacementRepresentationConstructionError>
    {
        let node = self.epoch.resources.graph().resource(resource).ok_or(
            ReplacementRepresentationConstructionError::ResourceAbsent(resource),
        )?;
        let descriptor = node
            .descriptor
            .as_deref()
            .ok_or(ReplacementRepresentationConstructionError::DescriptorAbsent(resource))?;
        let reims_vgpu_protocol::ResourceDescriptor::Buffer(descriptor) = descriptor else {
            return Err(
                ReplacementRepresentationConstructionError::UnsupportedDescriptor(node.kind),
            );
        };
        let backing =
            node.storage
                .ok_or(ReplacementRepresentationConstructionError::StorageAbsent(
                    resource,
                ))?;
        if matches!(
            route,
            reims_vgpu_core::RepresentationRoute::ImportedGuestTransfer { .. }
                | reims_vgpu_core::RepresentationRoute::HostStagingTransfer { .. }
        ) && self
            .epoch
            .resources
            .representation(
                backing,
                match route {
                    reims_vgpu_core::RepresentationRoute::ImportedGuestTransfer { .. } => {
                        reims_vgpu_core::GUEST_REPRESENTATION
                    }
                    reims_vgpu_core::RepresentationRoute::HostStagingTransfer { .. } => {
                        reims_vgpu_core::HOST_REPRESENTATION
                    }
                    _ => unreachable!("the transfer route was matched above"),
                },
            )
            .is_none()
        {
            return Err(ReplacementRepresentationConstructionError::TransferEndpointAbsent(route));
        }
        let memory = Self::owned_working_memory(route)?;
        let native = device
            .create_owned_working_buffer(descriptor.allocation_size, memory)
            .map_err(ReplacementRepresentationConstructionError::BufferAllocation)?;
        self.epoch
            .resources
            .create_execution_representation(
                backing,
                route,
                reims_vgpu_core::BackingView::Bytes,
                native,
            )
            .map_err(|failure| {
                ReplacementRepresentationConstructionError::Lifecycle(failure.reason)
            })
    }

    /// Construct both endpoints of an imported-transfer buffer route from one
    /// explicit bounded guest reference. The guest endpoint is the canonical
    /// guest representation; the ordinary execution endpoint remains a
    /// separately owned working buffer selected by topology.
    pub fn materialize_buffer_with_guest_endpoint(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
        guest: &reims_vgpu_memory::GuestRef,
    ) -> Result<reims_vgpu_protocol::RepresentationId, ReplacementRepresentationConstructionError>
    {
        self.materialize_buffer_with_guest_window(
            device,
            resource,
            reims_vgpu_memory::GuestWindow::contiguous(guest.clone()),
        )
    }

    pub fn materialize_buffer_with_guest_window(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
        guest: reims_vgpu_memory::GuestWindow,
    ) -> Result<reims_vgpu_protocol::RepresentationId, ReplacementRepresentationConstructionError>
    {
        let node = self.epoch.resources.graph().resource(resource).ok_or(
            ReplacementRepresentationConstructionError::ResourceAbsent(resource),
        )?;
        let descriptor = node
            .descriptor
            .as_deref()
            .ok_or(ReplacementRepresentationConstructionError::DescriptorAbsent(resource))?;
        let reims_vgpu_protocol::ResourceDescriptor::Buffer(descriptor) = descriptor else {
            return Err(
                ReplacementRepresentationConstructionError::UnsupportedDescriptor(node.kind),
            );
        };
        if guest.requested() != descriptor.allocation_size {
            return Err(
                ReplacementRepresentationConstructionError::GuestBufferLengthMismatch {
                    expected: descriptor.allocation_size,
                    actual: guest.requested(),
                },
            );
        }
        let backing =
            node.storage
                .ok_or(ReplacementRepresentationConstructionError::StorageAbsent(
                    resource,
                ))?;
        let (topology, mut capabilities) = device.representation_environment();
        capabilities.imported_transfer &= guest.runs().len() == 1;
        let route = Self::guest_transfer_route(descriptor.storage_mode(), topology, capabilities)?;
        match route {
            reims_vgpu_core::RepresentationRoute::ImportedGuestTransfer { working } => {
                if self
                    .epoch
                    .resources
                    .representation(backing, reims_vgpu_core::GUEST_REPRESENTATION)
                    .is_none()
                {
                    let imported = device
                        .create_imported_guest_buffer(&guest.runs()[0].guest)
                        .map_err(ReplacementRepresentationConstructionError::GuestBufferImport)?;
                    self.epoch
                        .resources
                        .create_representation(
                            backing,
                            reims_vgpu_core::RepresentationRoute::DirectGuestAlias,
                            imported,
                        )
                        .map_err(|failure| {
                            ReplacementRepresentationConstructionError::Lifecycle(failure.reason)
                        })?;
                }
                self.materialize_buffer(
                    device,
                    resource,
                    reims_vgpu_core::RepresentationRoute::ImportedGuestTransfer { working },
                )
            }
            reims_vgpu_core::RepresentationRoute::HostStagingTransfer { working } => {
                if self
                    .epoch
                    .resources
                    .representation(backing, reims_vgpu_core::HOST_REPRESENTATION)
                    .is_none()
                {
                    let staging = device
                        .create_host_staging_buffer_for_window(descriptor.allocation_size, guest)
                        .map_err(ReplacementRepresentationConstructionError::BufferAllocation)?;
                    self.epoch
                        .resources
                        .create_representation(
                            backing,
                            reims_vgpu_core::RepresentationRoute::HostStagingEndpoint,
                            staging,
                        )
                        .map_err(|failure| {
                            ReplacementRepresentationConstructionError::Lifecycle(failure.reason)
                        })?;
                }
                self.materialize_buffer(
                    device,
                    resource,
                    reims_vgpu_core::RepresentationRoute::HostStagingTransfer { working },
                )
            }
            _ => self.materialize_resource_with_route(device, resource, route),
        }
    }

    /// Materialize the one native representation class owned by the retained
    /// decoded descriptor. Callers cannot branch on object kind and assemble a
    /// construction rule outside this owner.
    fn materialize_resource_with_route(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
        route: reims_vgpu_core::RepresentationRoute,
    ) -> Result<reims_vgpu_protocol::RepresentationId, ReplacementRepresentationConstructionError>
    {
        let node = self.epoch.resources.graph().resource(resource).ok_or(
            ReplacementRepresentationConstructionError::ResourceAbsent(resource),
        )?;
        // The class, not the descriptor: what this builds and what every
        // later reader asks about must be one statement, or a descriptor
        // reachable here and absent there materializes an image nothing can
        // find. A plane view's declaration comes from its surface rather than
        // from itself, so it is an image this entry point cannot construct ---
        // a typed refusal, and not a hole in the class.
        match node
            .descriptor
            .as_deref()
            .ok_or(ReplacementRepresentationConstructionError::DescriptorAbsent(resource))?
            .native_representation_class()
        {
            Some(reims_vgpu_protocol::NativeRepresentationClass::Bytes) => {
                self.materialize_buffer(device, resource, route)
            }
            Some(reims_vgpu_protocol::NativeRepresentationClass::Image) => {
                self.materialize_texture(device, resource, route)
            }
            None => {
                Err(ReplacementRepresentationConstructionError::UnsupportedDescriptor(node.kind))
            }
        }
    }

    /// Plan and construct the representation from the decoded storage mode and
    /// this exact Vulkan epoch's structural capabilities.
    pub fn materialize_resource(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
    ) -> Result<reims_vgpu_protocol::RepresentationId, ReplacementRepresentationConstructionError>
    {
        let node = self.epoch.resources.graph().resource(resource).ok_or(
            ReplacementRepresentationConstructionError::ResourceAbsent(resource),
        )?;
        let descriptor = node
            .descriptor
            .as_deref()
            .ok_or(ReplacementRepresentationConstructionError::DescriptorAbsent(resource))?;
        let storage_mode = match descriptor {
            reims_vgpu_protocol::ResourceDescriptor::Buffer(descriptor) => {
                descriptor.storage_mode()
            }
            reims_vgpu_protocol::ResourceDescriptor::Texture(descriptor) => {
                descriptor.declaration.map_or(
                    reims_vgpu_protocol::StorageMode::Undeclared,
                    |declaration| declaration.storage_mode(),
                )
            }
            reims_vgpu_protocol::ResourceDescriptor::HeapTexture(descriptor) => {
                descriptor.declaration.storage_mode()
            }
            reims_vgpu_protocol::ResourceDescriptor::MapperIOSurfaceTextureView(descriptor) => {
                descriptor.declaration.storage_mode()
            }
            _ => {
                return Err(
                    ReplacementRepresentationConstructionError::UnsupportedDescriptor(node.kind),
                );
            }
        };
        let (topology, mut capabilities) = device.representation_environment();
        let backing =
            node.storage
                .ok_or(ReplacementRepresentationConstructionError::StorageAbsent(
                    resource,
                ))?;
        capabilities.imported_transfer &= self
            .epoch
            .resources
            .representation(backing, reims_vgpu_core::GUEST_REPRESENTATION)
            .is_some();
        let route = reims_vgpu_core::plan_representation(storage_mode, topology, capabilities)
            .map_err(ReplacementRepresentationConstructionError::RepresentationPlan)?;
        self.materialize_resource_with_route(device, resource, route)
    }

    /// Construct and publish an image from the complete decoded texture
    /// declaration retained by this exact resource generation. Render-target
    /// declarations eagerly create every contract-addressable mip/layer view,
    /// so immutable render projection never allocates a view while recording.
    fn materialize_texture(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
        route: reims_vgpu_core::RepresentationRoute,
    ) -> Result<reims_vgpu_protocol::RepresentationId, ReplacementRepresentationConstructionError>
    {
        let node = self.epoch.resources.graph().resource(resource).ok_or(
            ReplacementRepresentationConstructionError::ResourceAbsent(resource),
        )?;
        let descriptor = node
            .descriptor
            .as_deref()
            .ok_or(ReplacementRepresentationConstructionError::DescriptorAbsent(resource))?;
        let declaration = match descriptor {
            reims_vgpu_protocol::ResourceDescriptor::Texture(descriptor) => {
                descriptor.declaration.ok_or(
                    ReplacementRepresentationConstructionError::TextureDeclarationAbsent(resource),
                )?
            }
            reims_vgpu_protocol::ResourceDescriptor::HeapTexture(descriptor) => {
                descriptor.declaration
            }
            reims_vgpu_protocol::ResourceDescriptor::MapperIOSurfaceTextureView(descriptor) => {
                descriptor.declaration
            }
            _ => {
                return Err(
                    ReplacementRepresentationConstructionError::UnsupportedDescriptor(node.kind),
                );
            }
        };
        self.materialize_texture_declaration(device, resource, declaration, route)
    }

    fn materialize_texture_declaration(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
        declaration: reims_vgpu_protocol::TextureDeclaration,
        route: reims_vgpu_core::RepresentationRoute,
    ) -> Result<reims_vgpu_protocol::RepresentationId, ReplacementRepresentationConstructionError>
    {
        let node = self.epoch.resources.graph().resource(resource).ok_or(
            ReplacementRepresentationConstructionError::ResourceAbsent(resource),
        )?;
        let backing =
            node.storage
                .ok_or(ReplacementRepresentationConstructionError::StorageAbsent(
                    resource,
                ))?;
        if matches!(
            route,
            reims_vgpu_core::RepresentationRoute::ImportedGuestTransfer { .. }
                | reims_vgpu_core::RepresentationRoute::HostStagingTransfer { .. }
        ) && self
            .epoch
            .resources
            .representation(
                backing,
                match route {
                    reims_vgpu_core::RepresentationRoute::ImportedGuestTransfer { .. } => {
                        reims_vgpu_core::GUEST_REPRESENTATION
                    }
                    reims_vgpu_core::RepresentationRoute::HostStagingTransfer { .. } => {
                        reims_vgpu_core::HOST_REPRESENTATION
                    }
                    _ => unreachable!("the transfer route was matched above"),
                },
            )
            .is_none()
        {
            return Err(ReplacementRepresentationConstructionError::TransferEndpointAbsent(route));
        }
        let memory = Self::owned_working_memory(route)?;
        // This texture's views, not the backing's. Another texture declared
        // over the same guest range is a different texture with a different
        // format, and its views belong to its own image -- installing them
        // here is the same substitution the per-texture image key exists to
        // prevent, one layer down.
        let shader_views = self
            .epoch
            .resources
            .graph()
            .texture_binding_views_for_image_owner(resource)
            .map_err(ReplacementRepresentationConstructionError::TextureView)?;
        let native = device
            .create_owned_texture(declaration, Box::new([]), shader_views, memory)
            .map_err(ReplacementRepresentationConstructionError::TextureAllocation)?;
        let representation = self
            .epoch
            .resources
            .create_execution_representation(
                backing,
                route,
                reims_vgpu_core::BackingView::Image(reims_vgpu_core::ImageOwner::owning(resource)),
                native,
            )
            .map_err(|failure| {
                ReplacementRepresentationConstructionError::Lifecycle(failure.reason)
            })?;
        self.epoch
            .images
            .register_new_image(
                reims_vgpu_vulkan::replacement_image_state::ReplacementImageKey {
                    backing,
                    representation,
                },
                device.work_queue_family(),
            )
            .unwrap_or_else(|reason| {
                unreachable!(
                    "a newly allocated representation in this exact epoch has no prior image state: {reason:?}"
                )
            });
        Ok(representation)
    }

    /// Materialize one registered-surface plane view over its own plane
    /// backing, through the surface's exact page-backed staging allocation.
    ///
    /// The plane, not the surface, is the thing with image semantics: a
    /// surface allocation may declare several planes, each with its own
    /// offset, geometry, row pitch and pixel format, and a backing carries one
    /// execution representation and one layout. The staging allocation spans
    /// the whole surface because the plane's layout is allocation-relative;
    /// fragmentation is represented by the guest window itself and therefore
    /// selects staging independently of host import capability.
    pub fn materialize_io_surface_plane_view_with_guest_window(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
        guest: reims_vgpu_memory::GuestWindow,
    ) -> Result<reims_vgpu_protocol::RepresentationId, ReplacementRepresentationConstructionError>
    {
        let graph = self.epoch.resources.graph();
        let node = graph.resource(resource).ok_or(
            ReplacementRepresentationConstructionError::ResourceAbsent(resource),
        )?;
        let Some(reims_vgpu_protocol::ResourceDescriptor::IOSurfacePlaneView(view_descriptor)) =
            node.descriptor.as_deref()
        else {
            return Err(
                ReplacementRepresentationConstructionError::UnsupportedDescriptor(node.kind),
            );
        };
        let plane = view_descriptor
            .view
            .ok_or(ReplacementRepresentationConstructionError::DescriptorAbsent(resource))?;
        let backing =
            node.storage
                .ok_or(ReplacementRepresentationConstructionError::StorageAbsent(
                    resource,
                ))?;
        let mut parents = node.parents.iter().copied();
        let (Some(parent), None) = (parents.next(), parents.next()) else {
            return Err(ReplacementRepresentationConstructionError::ResourceAbsent(
                resource,
            ));
        };
        let Some(reims_vgpu_protocol::ResourceDescriptor::SurfaceBacking(surface)) = graph
            .resource(parent)
            .ok_or(ReplacementRepresentationConstructionError::ResourceAbsent(
                parent,
            ))?
            .descriptor
            .as_deref()
        else {
            return Err(ReplacementRepresentationConstructionError::DescriptorAbsent(parent));
        };
        if guest.requested() != surface.length {
            return Err(
                ReplacementRepresentationConstructionError::GuestTextureLengthMismatch {
                    expected: surface.length,
                    actual: guest.requested(),
                },
            );
        }
        let layout =
            Arc::new(surface.plane_linear_texture(plane).map_err(
                ReplacementRepresentationConstructionError::RegisteredSurfacePlaneLayout,
            )?);
        let declaration = layout
            .declaration
            .expect("a validated surface-plane layout carries its native declaration");
        let (topology, mut capabilities) = device.representation_environment();
        capabilities.imported_transfer = false;
        let route = Self::guest_transfer_route(
            reims_vgpu_protocol::StorageMode::Shared,
            topology,
            capabilities,
        )?;
        let reims_vgpu_core::RepresentationRoute::HostStagingTransfer { .. } = route else {
            return Err(
                ReplacementRepresentationConstructionError::RouteHasNoOwnedWorkingRepresentation(
                    route,
                ),
            );
        };
        let surface_length = surface.length;
        if self
            .epoch
            .resources
            .representation(backing, reims_vgpu_core::HOST_REPRESENTATION)
            .is_none()
        {
            let mut endpoint = device
                .create_host_staging_buffer_for_window(surface_length, guest)
                .map_err(ReplacementRepresentationConstructionError::BufferAllocation)?;
            endpoint
                .attach_linear_texture_layout(Arc::clone(&layout))
                .map_err(ReplacementRepresentationConstructionError::TextureEndpoint)?;
            self.epoch
                .resources
                .create_representation(
                    backing,
                    reims_vgpu_core::RepresentationRoute::HostStagingEndpoint,
                    endpoint,
                )
                .map_err(|failure| {
                    ReplacementRepresentationConstructionError::Lifecycle(failure.reason)
                })?;
        }
        self.materialize_texture_declaration(device, resource, declaration, route)
    }

    /// Bind one page-backed linear texture allocation as an exact transfer
    /// buffer before constructing its distinct optimal-image representation.
    /// The buffer is never selected for shader, attachment, or presentation
    /// use; it exists only under the reserved guest/host endpoint identity.
    fn materialize_texture_with_guest_endpoint_route(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
        guest: reims_vgpu_memory::GuestWindow,
        route: reims_vgpu_core::RepresentationRoute,
    ) -> Result<reims_vgpu_protocol::RepresentationId, ReplacementRepresentationConstructionError>
    {
        let node = self.epoch.resources.graph().resource(resource).ok_or(
            ReplacementRepresentationConstructionError::ResourceAbsent(resource),
        )?;
        let descriptor = node
            .descriptor
            .as_deref()
            .ok_or(ReplacementRepresentationConstructionError::DescriptorAbsent(resource))?;
        let reims_vgpu_protocol::ResourceDescriptor::Texture(descriptor) = descriptor else {
            return Err(
                ReplacementRepresentationConstructionError::UnsupportedDescriptor(node.kind),
            );
        };
        if guest.requested() != descriptor.allocation_size {
            return Err(
                ReplacementRepresentationConstructionError::GuestTextureLengthMismatch {
                    expected: descriptor.allocation_size,
                    actual: guest.requested(),
                },
            );
        }
        let texture_layout = Arc::new(descriptor.clone());
        let backing =
            node.storage
                .ok_or(ReplacementRepresentationConstructionError::StorageAbsent(
                    resource,
                ))?;
        match route {
            reims_vgpu_core::RepresentationRoute::ImportedGuestTransfer { .. } => {
                if self
                    .epoch
                    .resources
                    .representation(backing, reims_vgpu_core::GUEST_REPRESENTATION)
                    .is_none()
                {
                    let mut endpoint = device
                        .create_imported_guest_buffer(&guest.runs()[0].guest)
                        .map_err(ReplacementRepresentationConstructionError::GuestBufferImport)?;
                    endpoint
                        .attach_linear_texture_layout(Arc::clone(&texture_layout))
                        .map_err(ReplacementRepresentationConstructionError::TextureEndpoint)?;
                    self.epoch
                        .resources
                        .create_representation(
                            backing,
                            reims_vgpu_core::RepresentationRoute::DirectGuestAlias,
                            endpoint,
                        )
                        .map_err(|failure| {
                            ReplacementRepresentationConstructionError::Lifecycle(failure.reason)
                        })?;
                }
            }
            reims_vgpu_core::RepresentationRoute::HostStagingTransfer { .. } => {
                if self
                    .epoch
                    .resources
                    .representation(backing, reims_vgpu_core::HOST_REPRESENTATION)
                    .is_none()
                {
                    let mut endpoint = device
                        .create_host_staging_buffer_for_window(descriptor.allocation_size, guest)
                        .map_err(ReplacementRepresentationConstructionError::BufferAllocation)?;
                    endpoint
                        .attach_linear_texture_layout(Arc::clone(&texture_layout))
                        .map_err(ReplacementRepresentationConstructionError::TextureEndpoint)?;
                    self.epoch
                        .resources
                        .create_representation(
                            backing,
                            reims_vgpu_core::RepresentationRoute::HostStagingEndpoint,
                            endpoint,
                        )
                        .map_err(|failure| {
                            ReplacementRepresentationConstructionError::Lifecycle(failure.reason)
                        })?;
                }
            }
            _ => {
                return Err(
                    ReplacementRepresentationConstructionError::RouteHasNoOwnedWorkingRepresentation(
                        route,
                    ),
                );
            }
        }
        self.materialize_texture(device, resource, route)
    }

    pub fn materialize_texture_with_guest_endpoint(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
        guest: &reims_vgpu_memory::GuestRef,
    ) -> Result<reims_vgpu_protocol::RepresentationId, ReplacementRepresentationConstructionError>
    {
        self.materialize_texture_with_guest_window(
            device,
            resource,
            reims_vgpu_memory::GuestWindow::contiguous(guest.clone()),
        )
    }

    pub fn materialize_texture_with_guest_window(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
        guest: reims_vgpu_memory::GuestWindow,
    ) -> Result<reims_vgpu_protocol::RepresentationId, ReplacementRepresentationConstructionError>
    {
        let node = self.epoch.resources.graph().resource(resource).ok_or(
            ReplacementRepresentationConstructionError::ResourceAbsent(resource),
        )?;
        let descriptor = node
            .descriptor
            .as_deref()
            .ok_or(ReplacementRepresentationConstructionError::DescriptorAbsent(resource))?;
        let reims_vgpu_protocol::ResourceDescriptor::Texture(descriptor) = descriptor else {
            return Err(
                ReplacementRepresentationConstructionError::UnsupportedDescriptor(node.kind),
            );
        };
        let declaration = descriptor.declaration.ok_or(
            ReplacementRepresentationConstructionError::TextureDeclarationAbsent(resource),
        )?;
        let (topology, mut capabilities) = device.representation_environment();
        capabilities.imported_transfer &= guest.runs().len() == 1;
        let route = Self::guest_transfer_route(declaration.storage_mode(), topology, capabilities)?;
        self.materialize_texture_with_guest_endpoint_route(device, resource, guest, route)
    }

    /// Install a texture view created after its base image was materialized.
    /// The derived handle remains owned by the base representation, whose
    /// backing retirement also waits for every accepted use of that image.
    pub fn materialize_texture_view(
        &mut self,
        device: &ReplacementDeviceEpoch,
        resource: ResourceId<reims_vgpu_protocol::ResourceObject>,
    ) -> Result<(), ReplacementRepresentationConstructionError> {
        let view = self
            .epoch
            .resources
            .graph()
            .resolve_texture_binding_view(resource)
            .map_err(ReplacementRepresentationConstructionError::TextureView)?;
        // A resource that owns the image over its storage has no view to
        // install: it *is* the image. That is ownership and not the chain ---
        // a plane view names the surface as its base and still owns the image,
        // so a chain-keyed guard would try to install a view of the plane onto
        // the plane's own image.
        if view.resource == view.image_owner {
            return Err(
                ReplacementRepresentationConstructionError::UnsupportedDescriptor(
                    reims_vgpu_protocol::ObjectKind::Texture,
                ),
            );
        }
        // The view's own resolved backing, not the base's: a view over an
        // IOSurface plane resolves to that plane's backing, which is where the
        // image it derives from was materialized.
        let backing = self
            .epoch
            .resources
            .graph()
            .resolved_backing(resource)
            .ok_or(ReplacementRepresentationConstructionError::StorageAbsent(
                resource,
            ))?;
        // The base's image, because a binding view has none of its own: it is
        // installed onto the image the texture it views was materialized with.
        // For a plane view the base is that plane, which is the resource its
        // own materialization keyed the image by.
        let representation = self
            .epoch
            .resources
            .execution_representation_id(
                backing,
                reims_vgpu_core::BackingView::Image(reims_vgpu_core::ImageOwner::owning(
                    view.image_owner,
                )),
            )
            .map_err(ReplacementRepresentationConstructionError::Lifecycle)?;
        let native = self
            .epoch
            .resources
            .representation_mut(backing, representation)
            .ok_or(ReplacementRepresentationConstructionError::Lifecycle(
                reims_vgpu_core::ManagedBackingError::UnknownRepresentation,
            ))?;
        device
            .install_texture_view(native, view)
            .map_err(ReplacementRepresentationConstructionError::ShaderViewInstall)
    }

    /// Route one epoch timeline fact back to the semantic generation carried
    /// by native acceptance. A reset never promotes it into the new
    /// generation's publication domains.
    pub fn commit_completion(
        &mut self,
        fact: reims_vgpu_core::CompletionFact<Semantic>,
    ) -> Result<
        Vec<reims_vgpu_core::PublishedFact<Semantic>>,
        ReplacementExecutionCompletionError<Semantic>,
    > {
        let generation = fact.session_generation;
        let runtime = if self.active.generation.id() == generation {
            &mut self.active.runtime
        } else if let Some(runtime) = self.retired.get_mut(&generation) {
            runtime
        } else {
            return Err(ReplacementExecutionCompletionError::UnknownGeneration {
                generation,
                fact,
            });
        };
        reims_vgpu_core::commit_replay_semantic_completion(runtime, fact)
            .map_err(ReplacementExecutionCompletionError::Commit)
    }

    pub fn retire_transaction(
        &mut self,
        generation: SessionGenerationId,
        transaction: TransactionId,
    ) -> Result<(), ReplacementExecutionRetirementError> {
        let runtime = if self.active.generation.id() == generation {
            &mut self.active.runtime
        } else if let Some(runtime) = self.retired.get_mut(&generation) {
            runtime
        } else {
            return Err(ReplacementExecutionRetirementError::UnknownGeneration(
                generation,
            ));
        };
        reims_vgpu_core::commit_replay_retirement(runtime, &mut self.epoch.native, transaction)
            .map_err(ReplacementExecutionRetirementError::Commit)?;
        if generation != self.active.generation.id()
            && self
                .retired
                .get(&generation)
                .is_some_and(|runtime| runtime.live_transactions() == 0)
        {
            self.retired.remove(&generation);
        }
        Ok(())
    }
}

