impl<Completion> PendingReplacementGuestUploadRecording<Completion> {
    pub const fn transaction(&self) -> TransactionId {
        self.prepared.admitted().transaction.id
    }

    pub fn try_complete(self) -> ReplacementGuestUploadRecordingPoll<Completion> {
        let Self {
            pending,
            prepared,
            manifest,
            chain,
            recording_exec,
            recording_origins,
            include_resource_state_admission,
            continuation,
        } = self;
        match pending.try_complete() {
            ReplacementAdmittedRecordingPoll::Pending(pending) => {
                ReplacementGuestUploadRecordingPoll::Pending(Self {
                    pending,
                    prepared,
                    manifest,
                    chain,
                    recording_exec,
                    recording_origins,
                    include_resource_state_admission,
                    continuation,
                })
            }
            ReplacementAdmittedRecordingPoll::Completed(Ok(recorded)) => {
                ReplacementGuestUploadRecordingPoll::Completed(Ok(
                    ReplacementRecordedGuestUploadPhase {
                        recorded,
                        prepared,
                        manifest,
                        chain,
                        continuation,
                    },
                ))
            }
            ReplacementAdmittedRecordingPoll::Completed(Err(failure)) => {
                let ReplacementAdmittedRecordingDispatchFailure {
                    reason,
                    generation,
                    resources,
                    image_states,
                } = *failure;
                ReplacementGuestUploadRecordingPoll::Completed(Err(Box::new(
                    ReplacementGuestUploadRecordingDispatchFailure {
                        reason,
                        phase: ReplacementPreparedGuestUploadPhase {
                            prepared,
                            manifest,
                            chain,
                            recording_exec,
                            recording_origins,
                            include_resource_state_admission,
                            continuation,
                            envelope: ReplacementPreparedExecEnvelope {
                                resources,
                                image_states,
                            },
                        },
                        generation,
                    },
                )))
            }
        }
    }

    #[cfg(test)]
    fn wait(
        self,
    ) -> Result<
        ReplacementRecordedGuestUploadPhase<Completion>,
        Box<ReplacementGuestUploadRecordingDispatchFailure<Completion>>,
    > {
        let Self {
            pending,
            prepared,
            manifest,
            chain,
            recording_exec,
            recording_origins,
            include_resource_state_admission,
            continuation,
        } = self;
        match pending.wait() {
            Ok(recorded) => Ok(ReplacementRecordedGuestUploadPhase {
                recorded,
                prepared,
                manifest,
                chain,
                continuation,
            }),
            Err(failure) => {
                let ReplacementAdmittedRecordingDispatchFailure {
                    reason,
                    generation,
                    resources,
                    image_states,
                } = *failure;
                Err(Box::new(ReplacementGuestUploadRecordingDispatchFailure {
                    reason,
                    phase: ReplacementPreparedGuestUploadPhase {
                        prepared,
                        manifest,
                        chain,
                        recording_exec,
                        recording_origins,
                        include_resource_state_admission,
                        continuation,
                        envelope: ReplacementPreparedExecEnvelope {
                            resources,
                            image_states,
                        },
                    },
                    generation,
                }))
            }
        }
    }
}

