/// Why one exec could not take its image claims.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum ReplacementExecImagePreparationRefusal {
    /// The backend's own image-state rule declined the plan.
    Images(reims_vgpu_vulkan::replacement_exec_image::ExecImageStateError),
    /// A transaction ahead of this one in its own domain has not submitted, so
    /// this one may not take an exclusive image claim yet.
    ///
    /// An image representation carries one prepared transition at a time, and
    /// a domain submits in sequence. A claim taken by a later transaction is
    /// not merely early, it is unresolvable: the earlier one cannot prepare an
    /// image the later one holds, and the later one cannot submit or cancel
    /// while the earlier one holds the domain. Both then retry for the life of
    /// the device with every stall counter reading healthy, because neither
    /// has failed.
    ///
    /// This asks about *any* unsubmitted predecessor, not only an issued head.
    /// A rule that asked only about the issued head let the cycle form one
    /// step earlier: with nothing issued, a transaction at sequence 58 claimed
    /// an image and the transaction at sequence 56 then became the head and
    /// needed it.
    ///
    /// The predecessor's own position travels with the refusal so the log can
    /// be read against `replacement_submission_order` directly.
    BehindUnsubmittedPredecessor(reims_vgpu_core::UnsubmittedPredecessor),
    /// No runtime tracks this transaction's order, so nothing can be said
    /// about what it sits behind.
    ///
    /// Distinct from taking the claim: an exec whose order cannot be found is
    /// not an exec that is free to claim, it is one this device has lost track
    /// of, and silently allowing it is how an ordering rule stops covering the
    /// population it was written for.
    SubmissionOrderUntracked,
}

type ReplacementExecResourceCancellation = reims_vgpu_core::ExecResourceCancellationResult<
    ReplacementNativeRepresentation,
    ResolvedComputeDispatch,
    ReplacementComputePipelineVariant,
    ResolvedRenderDispatch,
    ReplacementRenderPipelineVariant,
>;
type ReplacementComputePreparationStepFailure = reims_vgpu_core::ExecResourcePreparationStepFailure<
    (
        reims_vgpu_core::ComputeDispatchPreparationError,
        reims_vgpu_core::ComputeDispatchPreparationInput<ReplacementComputePipelineVariant>,
    ),
    reims_vgpu_core::ComputeDispatchPreparationInput<ReplacementComputePipelineVariant>,
>;
type ReplacementRenderPreparationStepFailure = reims_vgpu_core::ExecResourcePreparationStepFailure<
    (
        reims_vgpu_core::RenderDispatchPreparationError,
        reims_vgpu_core::RenderDispatchPreparationInput<ReplacementRenderPipelineVariant>,
    ),
    reims_vgpu_core::RenderDispatchPreparationInput<ReplacementRenderPipelineVariant>,
>;

/// Which render preparation step refused, and why.
///
/// Every arm of [`reims_vgpu_core::RenderDispatchPreparationError`] is a hard
/// refusal — none of them is a "not ready yet" — so this names lost guest work
/// rather than expected control flow, and the variant is what says which
/// contract term the dispatch failed to satisfy.
fn render_step_failure_name(failure: &ReplacementRenderPreparationStepFailure) -> String {
    match failure {
        reims_vgpu_core::ExecResourcePreparationStepFailure::TransactionMismatch { .. } => {
            "TransactionMismatch".to_string()
        }
        reims_vgpu_core::ExecResourcePreparationStepFailure::PositionOccupied { .. } => {
            "PositionOccupied".to_string()
        }
        reims_vgpu_core::ExecResourcePreparationStepFailure::Preparation((reason, _)) => {
            format!("{reason:?}")
        }
    }
}

pub(crate) enum ReplacementExecAutomaticPreparationError {
    OriginCountMismatch {
        operations: usize,
        origins: usize,
    },
    ManifestTransactionMismatch {
        expected: TransactionId,
        actual: TransactionId,
    },
    ManifestSubmissionMismatch {
        expected: SubmissionId,
        actual: SubmissionId,
    },
    ComputeLeaseAbsent(usize),
    RenderLeaseAbsent(usize),
    InfoEvaluationAbsent(usize),
    BufferBlit {
        position: usize,
        failure: Box<
            reims_vgpu_core::ExecResourcePreparationStepFailure<
                Box<reims_vgpu_core::BufferBlitPreparationFailure>,
                reims_vgpu_core::ResolvedBlit,
            >,
        >,
        prefix: ReplacementExecResourceCancellation,
    },
    ImageBlit {
        position: usize,
        failure: Box<
            reims_vgpu_core::ExecResourcePreparationStepFailure<
                Box<reims_vgpu_core::ImageBlitPreparationFailure>,
                reims_vgpu_core::ResolvedBlit,
            >,
        >,
        prefix: ReplacementExecResourceCancellation,
    },
    Compute {
        position: usize,
        failure: Box<ReplacementComputePreparationStepFailure>,
        prefix: ReplacementExecResourceCancellation,
    },
    Render {
        position: usize,
        failure: Box<ReplacementRenderPreparationStepFailure>,
        prefix: ReplacementExecResourceCancellation,
    },
    Info {
        position: usize,
        failure: Box<
            reims_vgpu_core::ExecResourcePreparationStepFailure<
                Box<reims_vgpu_core::InfoQueryPreparationFailure>,
                reims_vgpu_core::EvaluatedInfoQuery,
            >,
        >,
        prefix: ReplacementExecResourceCancellation,
    },
    IndirectRange {
        position: usize,
        failure: Box<
            reims_vgpu_core::ExecResourcePreparationStepFailure<
                (
                    reims_vgpu_core::IndirectRangeReadbackError,
                    reims_vgpu_core::ResolvedIndirectCommand,
                ),
                reims_vgpu_core::ResolvedIndirectCommand,
            >,
        >,
        prefix: ReplacementExecResourceCancellation,
    },
    ResourceStates {
        failure: Box<ReplacementResourceStatePreparationFailure>,
        prefix: ReplacementExecResourceCancellation,
    },
    ContentSynchronization {
        reason: reims_vgpu_core::ContentSynchronizationError,
        prefix: ReplacementExecResourceCancellation,
    },
    HostIngress {
        reason: ReplacementHostIngressPreparationError,
        prefix: ReplacementExecResourceCancellation,
    },
    Assembly {
        reason: reims_vgpu_core::ExecResourcePreparationError,
        cancellation: ReplacementExecResourceCancellation,
    },
}

impl ReplacementExecAutomaticPreparationError {
    /// Which preparation step refused.
    ///
    /// This tree carries owners that cannot derive `Debug`, so the name is
    /// what crosses into a diagnostic. It is the phase, not the reason, and
    /// that is the level a retained coordinator failure can report.
    pub fn name(&self) -> String {
        match self {
            Self::Render {
                position, failure, ..
            } => {
                format!("Render[{position}]:{}", render_step_failure_name(failure))
            }
            Self::ContentSynchronization { reason, .. } => {
                format!("ContentSynchronization:{reason:?}")
            }
            Self::HostIngress { reason, .. } => format!("HostIngress:{reason:?}"),
            Self::Assembly { reason, .. } => format!("Assembly:{reason:?}"),
            _ => self.variant().to_string(),
        }
    }

    const fn variant(&self) -> &'static str {
        match self {
            Self::OriginCountMismatch { .. } => "OriginCountMismatch",
            Self::ManifestTransactionMismatch { .. } => "ManifestTransactionMismatch",
            Self::ManifestSubmissionMismatch { .. } => "ManifestSubmissionMismatch",
            Self::ComputeLeaseAbsent { .. } => "ComputeLeaseAbsent",
            Self::RenderLeaseAbsent { .. } => "RenderLeaseAbsent",
            Self::InfoEvaluationAbsent { .. } => "InfoEvaluationAbsent",
            Self::BufferBlit { .. } => "BufferBlit",
            Self::ImageBlit { .. } => "ImageBlit",
            Self::Compute { .. } => "Compute",
            Self::Render { .. } => "Render",
            Self::Info { .. } => "Info",
            Self::IndirectRange { .. } => "IndirectRange",
            Self::ResourceStates { .. } => "ResourceStates",
            Self::ContentSynchronization { .. } => "ContentSynchronization",
            Self::HostIngress { .. } => "HostIngress",
            Self::Assembly { .. } => "Assembly",
        }
    }
}

