#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) enum ReplacementExecResourceTableError {
    TailPopulated {
        object: u32,
        nonzero_bytes: u32,
    },
    /// A resource-table entry names an object-table slot that resolves to no
    /// live resource.
    ///
    /// `slot` is what separates the two cases, and they are not the same
    /// failure: an undeclared name can still be bound by a later packet, while
    /// a released one is a name the guest has finished with, whose resource is
    /// gone and whose next declaration creates a different object.
    ResourceAbsent {
        task: reims_vgpu_protocol::TaskId,
        object: reims_vgpu_protocol::ObjectTableRef<reims_vgpu_protocol::ResourceObject>,
        slot: reims_vgpu_core::ObjectSlotState,
    },
    AliasClosureAbsent(ResourceId<reims_vgpu_protocol::ResourceObject>),
    BackingAbsent(reims_vgpu_protocol::BackingId),
}

impl ReplacementExecResourceTableError {
    /// Whether no later guest packet can make this table entry resolvable.
    ///
    /// A resource-table entry naming a *released* slot is the one arm that can
    /// never come good. The guest has finished with that name, its resource is
    /// gone, and the next declaration for the name creates a different object
    /// under a new generation -- so re-offering the packet asks a question
    /// whose answer cannot change, forever, while the channel behind it is
    /// parked.
    ///
    /// An *undeclared* slot is the opposite and must keep waiting: no
    /// declaration this device admitted has named it yet, and a packet that
    /// has not arrived is exactly what binds it. The other arms are a decoded
    /// shape, an alias closure and a backing, none of which is a statement
    /// about a name the guest has retired.
    ///
    /// A terminal refusal here is still a lost EXEC, and it is reported as
    /// one. That is the trade this makes: one command lost with its reason on
    /// the fail channel, against a device that stops. If these appear in
    /// volume the question to ask is not whether to wait longer but whether
    /// this device released the object too early -- the refusal names the task
    /// and the slot so that question stays answerable.
    pub(crate) const fn is_terminal_refusal(&self) -> bool {
        match self {
            Self::ResourceAbsent {
                slot: reims_vgpu_core::ObjectSlotState::Released,
                ..
            } => true,
            Self::ResourceAbsent { .. }
            | Self::TailPopulated { .. }
            | Self::AliasClosureAbsent(_)
            | Self::BackingAbsent(_) => false,
        }
    }
}

impl ReplacementDecodedExecAdmissionError {
    /// See [`ReplacementExecResourceTableError::is_terminal_refusal`]. Only the
    /// resource table can refuse in a way a later packet cannot repair;
    /// decode, access compilation and runtime admission are all repairable or
    /// are decode-level shapes.
    pub(crate) const fn is_terminal_refusal(&self) -> bool {
        match self {
            Self::ResourceTable(reason) => reason.is_terminal_refusal(),
            Self::Canonical(_) | Self::Accesses(_) | Self::Admission(_) => false,
        }
    }
}

impl ReplacementExecAutomaticPreparationError {
    /// The backing this refused on and what was wrong with it.
    ///
    /// See [`reims_vgpu_core::RenderDispatchPreparationError::backing_fault`].
    /// Only the two dispatch arms can carry one: a blit or an info query names
    /// its backing through a different failure entirely.
    pub(crate) fn backing_fault(
        &self,
    ) -> Option<(
        reims_vgpu_protocol::BackingId,
        reims_vgpu_core::ManagedBackingError,
    )> {
        match self {
            Self::Compute { failure, .. } => match failure.as_ref() {
                reims_vgpu_core::ExecResourcePreparationStepFailure::Preparation((reason, _)) => {
                    reason.backing_fault()
                }
                _ => None,
            },
            Self::Render { failure, .. } => match failure.as_ref() {
                reims_vgpu_core::ExecResourcePreparationStepFailure::Preparation((reason, _)) => {
                    reason.backing_fault()
                }
                _ => None,
            },
            _ => None,
        }
    }

    /// The backing a `StaleExecutionRepresentation` names, if that is what
    /// refused this resource preparation.
    pub(crate) fn stale_backing(&self) -> Option<reims_vgpu_protocol::BackingId> {
        match self.backing_fault() {
            Some((backing, reims_vgpu_core::ManagedBackingError::StaleExecutionRepresentation)) => {
                Some(backing)
            }
            _ => None,
        }
    }

    /// The backing with no execution representation yet, if that is what
    /// refused this resource preparation.
    ///
    /// See
    /// [`reims_vgpu_core::RenderDispatchPreparationError::missing_representation_backing`]:
    /// this is the repairable one, and leaving it unrepaired holds a whole
    /// submission domain rather than costing one command.
    pub(crate) fn missing_representation_backing(&self) -> Option<reims_vgpu_protocol::BackingId> {
        match self.backing_fault() {
            Some((
                backing,
                reims_vgpu_core::ManagedBackingError::MissingExecutionRepresentation,
            )) => Some(backing),
            _ => None,
        }
    }
}

impl<Completion> ReplacementExecIngressPreparationError<Completion> {
    /// See [`ReplacementExecResourceTableError::is_terminal_refusal`].
    pub(crate) const fn is_terminal_refusal(&self) -> bool {
        match self {
            Self::Admission(reason) => reason.is_terminal_refusal(),
            Self::Direct(_) | Self::IndirectRange(_) => false,
        }
    }
}

impl<Completion> ReplacementExecIngressDispatchFailure<Completion> {
    /// See [`ReplacementExecAutomaticPreparationError::stale_backing`].
    pub(crate) fn stale_backing(&self) -> Option<reims_vgpu_protocol::BackingId> {
        match self {
            Self::DirectResources(ReplacementResourceReadyExecFailure::Resources {
                reason,
                ..
            }) => reason.stale_backing(),
            _ => None,
        }
    }

    /// See [`ReplacementExecResourceTableError::is_terminal_refusal`].
    pub(crate) const fn is_terminal_refusal(&self) -> bool {
        match self {
            Self::Ingress(reason) => reason.is_terminal_refusal(),
            Self::DirectDispatch(ReplacementResourceReadyDispatchFailure::Resolution(failure)) => {
                failure.reason.is_terminal_refusal()
            }
            Self::GuestUploadResolution(failure) => failure.reason.is_terminal_refusal(),
            Self::DirectResources(_)
            | Self::DirectDispatch(_)
            | Self::GuestUploadPhase(_)
            | Self::GuestUploadDispatch(_)
            | Self::IndirectRangeReadiness { .. }
            | Self::IndirectRange(_) => false,
        }
    }
}

/// What a standalone invalidation resolved to.
///
/// An invalidation whose records all name slots this device holds no resource
/// for asked for a validity move that is already true, so it is a contract
/// no-op rather than a refusal. Making that an outcome rather than an error is
/// what lets the packet be admitted, consume its completion stamp and advance
/// its channel, which a refusal cannot do.
#[derive(Clone, Debug, PartialEq)]
pub(crate) enum ReplacementResolvedInvalidation {
    Lifecycle(Box<reims_vgpu_core::ResolvedResourceLifecycle>),
    Satisfied,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) enum ReplacementStandaloneInvalidationError {
    UnknownTask(reims_vgpu_protocol::TaskId),
    ConflictingAliasValidity {
        backing: reims_vgpu_protocol::BackingId,
        first: crate::runtime::decode::fifo::InvalidateValidityOps,
        position: usize,
        found: crate::runtime::decode::fifo::InvalidateValidityOps,
    },
    ResourceTable(ReplacementExecResourceTableError),
}

impl ReplacementStandaloneInvalidationError {
    /// Whether no later guest packet can make this invalidation applicable.
    ///
    /// An invalidation record names one object-table slot and moves that
    /// resource's host/guest validity bits. A slot this device holds no
    /// resource for has no validity state to move, so the record is a no-op --
    /// and holding it is worse than dropping it, because a resource that
    /// arrives in that slot later arrives with its own initial validity and a
    /// deferred record would then overwrite it.
    ///
    /// The other arms are not this. An unknown task and an empty record are
    /// decode-level shapes, and a conflicting alias validity is a disagreement
    /// inside one record rather than a wait.
    pub(crate) const fn is_terminal_refusal(&self) -> bool {
        match self {
            Self::ResourceTable(ReplacementExecResourceTableError::ResourceAbsent { .. }) => true,
            Self::ResourceTable(
                ReplacementExecResourceTableError::TailPopulated { .. }
                | ReplacementExecResourceTableError::AliasClosureAbsent(_)
                | ReplacementExecResourceTableError::BackingAbsent(_),
            )
            | Self::UnknownTask(_)
            | Self::ConflictingAliasValidity { .. } => false,
        }
    }
}

fn replacement_backing_access(
    hazard_domain: reims_vgpu_protocol::HazardDomainId,
    backing: reims_vgpu_protocol::BackingId,
    resource: Option<ResourceId<reims_vgpu_protocol::ResourceObject>>,
    region: reims_vgpu_core::BackingRegion,
    mode: reims_vgpu_core::AccessMode,
    stages: reims_vgpu_core::StageScope,
) -> reims_vgpu_core::AccessIntent {
    let scope = match region {
        reims_vgpu_core::BackingRegion::Whole => reims_vgpu_core::AccessScope::WholeBacking,
        reims_vgpu_core::BackingRegion::Linear(range) => {
            reims_vgpu_core::AccessScope::Linear(range)
        }
        reims_vgpu_core::BackingRegion::Image(region) => reims_vgpu_core::AccessScope::Image(
            reims_vgpu_core::ImageSubresourceRange::new(
                region.aspect,
                region.mip,
                1,
                region.layer,
                1,
                Some(region.texels),
            )
            .expect("one exact backing image region is nonempty"),
        ),
    };
    reims_vgpu_core::AccessIntent::for_backing(
        hazard_domain,
        backing,
        resource,
        scope,
        mode,
        stages,
    )
    .expect("a backing region cannot have whole-domain scope")
}

fn replacement_info_destination(
    operation: &reims_vgpu_core::ResolvedInfoOperation,
) -> (
    ResourceId<reims_vgpu_protocol::ResourceObject>,
    reims_vgpu_protocol::BackingId,
    reims_vgpu_core::LinearRange,
) {
    match operation {
        reims_vgpu_core::ResolvedInfoOperation::RenderPipelineState { reply, .. }
        | reims_vgpu_core::ResolvedInfoOperation::ComputePipelineState { reply, .. }
        | reims_vgpu_core::ResolvedInfoOperation::ResourceHost { reply, .. }
        | reims_vgpu_core::ResolvedInfoOperation::HeapHost { reply, .. }
        | reims_vgpu_core::ResolvedInfoOperation::SamplerHost { reply, .. }
        | reims_vgpu_core::ResolvedInfoOperation::HeapTextureSizeAndAlign { reply, .. }
        | reims_vgpu_core::ResolvedInfoOperation::RenderPipelineImageblock { reply, .. }
        | reims_vgpu_core::ResolvedInfoOperation::ComputePipelineImageblock { reply, .. }
        | reims_vgpu_core::ResolvedInfoOperation::RateMapInfo { reply, .. }
        | reims_vgpu_core::ResolvedInfoOperation::MapCoordinate { reply, .. } => {
            (reply.resource, reply.backing, reply.range)
        }
        reims_vgpu_core::ResolvedInfoOperation::CopyRateParameterBuffer { destination, .. } => {
            (destination.resource, destination.backing, destination.range)
        }
    }
}

