#[cfg(feature = "host-window")]
fn completed_present_route(
    window: Option<ReplacementNativeWindowPresentOutcome>,
    fallback: reims_vgpu_core::PresentationRoute,
) -> Result<reims_vgpu_core::PresentationRoute, ReplacementNativeWindowPresentOutcome> {
    match window {
        Some(ReplacementNativeWindowPresentOutcome::Wsi(
            reims_vgpu_vulkan::replacement_window_present::ReplacementWindowPresentOutcome::Presented { .. },
        )) => Ok(reims_vgpu_core::PresentationRoute::Resident),
        Some(reason) => Err(reason),
        None => Ok(fallback),
    }
}

fn apply_display_present_notification(
    host: &mut (impl crate::runtime::host::HostMemory + crate::runtime::host::HostControl),
    interrupt_status: &std::sync::atomic::AtomicU32,
    notification: reims_vgpu_core::DisplayPresentNotification,
) -> Result<(), crate::runtime::host::MemError> {
    let reims_vgpu_core::DisplayPresentNotification::Deliver {
        page,
        pending,
        interrupt_bit,
        ..
    } = notification
    else {
        return Ok(());
    };
    let pending_gpa = page
        .gpa
        .checked_add(reims_vgpu_core::DISPLAY_SHARED_PENDING_OFFSET)
        .ok_or(crate::runtime::host::MemError::Overflow)?;
    let mut pending_le = [0u8; 4];
    reims_vgpu_core::endian::st32(&mut pending_le, pending);
    host.write_gpa(pending_gpa, &pending_le)?;
    interrupt_status.fetch_or(interrupt_bit, std::sync::atomic::Ordering::AcqRel);
    host.enqueue(crate::runtime::host::HostAction::irq_gfx());
    Ok(())
}

