#[cfg(feature = "host-window")]
fn synchronize_present_stream(
    streams: &mut BTreeMap<reims_vgpu_protocol::SurfaceId, reims_vgpu_core::PresentStream>,
    surface: reims_vgpu_protocol::SurfaceId,
    offered: reims_vgpu_core::SwapchainState,
) -> Result<
    (),
    (
        reims_vgpu_core::SwapchainState,
        reims_vgpu_core::SwapchainState,
    ),
> {
    match streams.entry(surface) {
        std::collections::btree_map::Entry::Vacant(entry) => {
            entry.insert(reims_vgpu_core::PresentStream::new(surface, offered));
        }
        std::collections::btree_map::Entry::Occupied(mut entry) => {
            let current = entry.get().current();
            if offered.generation < current.generation
                || (offered.generation == current.generation
                    && offered.image_count != current.image_count)
            {
                return Err((current, offered));
            }
            if offered.generation > current.generation {
                entry.get_mut().replace(offered);
            }
        }
    }
    Ok(())
}

