/// The one composition root for a replacement device session. Pipeline,
/// Vulkan, semantic transaction, canonical resource, image-layout, recording,
/// and queue owners cannot be constructed with unrelated generation or epoch
/// identities through this boundary.
pub(crate) struct ReplacementRuntimeSession<Semantic> {
    session: ReplacementSession,
    execution: ReplacementExecutionOwners<Semantic>,
    submissions: reims_vgpu_core::SubmissionTracker,
    tasks: reims_vgpu_core::TaskTable,
    mapper: reims_vgpu_core::MapperService,
    display: reims_vgpu_core::DisplayHandshake,
    cursor: reims_vgpu_core::CursorState,
    #[cfg(feature = "host-window")]
    present_streams: BTreeMap<reims_vgpu_protocol::SurfaceId, reims_vgpu_core::PresentStream>,
    #[cfg(feature = "host-window")]
    retired_swapchains: std::collections::VecDeque<(
        reims_vgpu_protocol::SurfaceId,
        reims_vgpu_protocol::SwapchainGenerationId,
    )>,
}

/// Recorded owners the Vulkan epoch holds parked behind a predecessor.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
