    fn project_decoded_exec_streams<Completion>(
        &mut self,
        task: reims_vgpu_protocol::TaskId,
        streams: Box<[crate::runtime::replacement_exec_decode::DecodedReplacementStream]>,
    ) -> Result<
        crate::runtime::replacement_exec_decode::ProjectedReplacementExec<Completion>,
        crate::runtime::replacement_exec_decode::ReplacementOperationProjectionFailure,
    > {
        self.project_decoded_exec_streams_with_icb_reader(
            task,
            streams,
            &mut |_, _| {
                Err(
                    crate::runtime::replacement_exec_decode::ReplacementIcbCommandMemoryTransportError::Unavailable,
                )
            },
        )
    }

    fn decode_canonical_exec<Completion>(
        &mut self,
        identity: reims_vgpu_protocol::SubmissionIdentity,
        prologue: reims_vgpu_core::ExecPrologue<CanonicalReplacementOperation<Completion>>,
        accesses: Box<[reims_vgpu_core::AccessIntent]>,
        streams: &[Vec<u8>],
    ) -> Result<CanonicalReplacementExecTransaction<Completion>, ReplacementCanonicalExecDecodeError>
    {
        self.decode_canonical_exec_with_icb_reader(
            identity,
            prologue,
            accesses,
            streams,
            &mut |_, _| {
                Err(
                    crate::runtime::replacement_exec_decode::ReplacementIcbCommandMemoryTransportError::Unavailable,
                )
            },
        )
    }

    fn decode_canonical_exec_with_icb_reader<Completion>(
        &mut self,
        identity: reims_vgpu_protocol::SubmissionIdentity,
        prologue: reims_vgpu_core::ExecPrologue<CanonicalReplacementOperation<Completion>>,
        accesses: Box<[reims_vgpu_core::AccessIntent]>,
        streams: &[Vec<u8>],
        read_memory: &mut impl FnMut(
            reims_vgpu_protocol::TaskId,
            reims_vgpu_core::IndirectCommandMemoryReadPlan,
        ) -> Result<
            Vec<u8>,
            crate::runtime::replacement_exec_decode::ReplacementIcbCommandMemoryTransportError,
        >,
    ) -> Result<CanonicalReplacementExecTransaction<Completion>, ReplacementCanonicalExecDecodeError>
    {
        let decoded =
            crate::runtime::replacement_exec_decode::decode_replacement_exec_streams(streams)
                .map_err(ReplacementCanonicalExecDecodeError::Decode)?;
        let streams = self
            .project_decoded_exec_streams_with_icb_reader(identity.task, decoded, read_memory)
            .map_err(ReplacementCanonicalExecDecodeError::Projection)?;
        Ok(reims_vgpu_core::ExecTransaction {
            identity,
            prologue,
            streams,
            accesses,
        })
    }

    fn project_decoded_exec_streams_with_icb_reader<Completion>(
        &mut self,
        task: reims_vgpu_protocol::TaskId,
        streams: Box<[crate::runtime::replacement_exec_decode::DecodedReplacementStream]>,
        read_memory: &mut impl FnMut(
            reims_vgpu_protocol::TaskId,
            reims_vgpu_core::IndirectCommandMemoryReadPlan,
        ) -> Result<
            Vec<u8>,
            crate::runtime::replacement_exec_decode::ReplacementIcbCommandMemoryTransportError,
        >,
    ) -> Result<
        crate::runtime::replacement_exec_decode::ProjectedReplacementExec<Completion>,
        crate::runtime::replacement_exec_decode::ReplacementOperationProjectionFailure,
    > {
        let namespace_checkpoint = self.execution.active.namespaces.clone();
        let indirect_checkpoint = self.execution.active.indirect.clone();
        let projection_state = std::cell::RefCell::new(
            crate::runtime::replacement_exec_decode::ReplacementRecordProjectionState::default(),
        );
        let mut projection =
            crate::runtime::replacement_exec_decode::project_replacement_exec_streams(
                streams,
                |boundary| {
                    projection_state.borrow_mut().encoder_boundary(boundary);
                    reims_vgpu_core::ResolvedOperation::EncoderBoundary(boundary)
                },
                |_boundary, record| {
                    crate::runtime::replacement_exec_decode::project_replacement_record_with_icb_reader(
                    self,
                    task,
                    &mut projection_state.borrow_mut(),
                    record,
                    read_memory,
                )
                },
            );
        if projection.is_err() {
            self.execution.active.namespaces = namespace_checkpoint;
            self.execution.active.indirect = indirect_checkpoint;
        } else if let Ok(streams) = projection.as_mut() {
            crate::runtime::replacement_exec_decode::mark_render_dispatch_encoder_boundaries(
                streams,
            );
        }
        projection
    }

