    pub fn declare_sampler(
        &mut self,
        task: reims_vgpu_protocol::TaskId,
        reference: reims_vgpu_protocol::SerializerRef<SamplerObject>,
        descriptor: SamplerDescriptor,
    ) -> Result<ResourceId<SamplerObject>, ReplacementObjectDeclarationError> {
        if reference.get() == 0 {
            return Err(ReplacementObjectDeclarationError::UnboundReference);
        }
        if self
            .execution
            .active
            .namespaces
            .resolve_sampler(task, reference)
            .is_some()
        {
            return Err(ReplacementObjectDeclarationError::DuplicateReference);
        }
        let sampler = self
            .execution
            .active
            .namespaces
            .publish_sampler(task, reference)
            .map_err(ReplacementObjectDeclarationError::Namespace)?;
        if let Err(error) = self.execution.active.samplers.declare(sampler, descriptor) {
            let released = self
                .execution
                .active
                .namespaces
                .release_sampler(task, reference);
            debug_assert!(released);
            return Err(ReplacementObjectDeclarationError::State(error));
        }
        Ok(sampler)
    }

    pub fn resolve_sampler(
        &self,
        task: reims_vgpu_protocol::TaskId,
        reference: reims_vgpu_protocol::SerializerRef<SamplerObject>,
    ) -> Option<(ResourceId<SamplerObject>, Arc<SamplerDescriptor>)> {
        let sampler = self
            .execution
            .active
            .namespaces
            .resolve_sampler(task, reference)?;
        let descriptor = self.execution.active.samplers.resolve(sampler);
        debug_assert!(descriptor.is_some());
        descriptor.map(|descriptor| (sampler, descriptor))
    }

    pub fn retire_sampler(
        &mut self,
        task: reims_vgpu_protocol::TaskId,
        reference: reims_vgpu_protocol::SerializerRef<SamplerObject>,
    ) -> Result<Arc<SamplerDescriptor>, ReplacementObjectRetirementError> {
        let sampler = self
            .execution
            .active
            .namespaces
            .resolve_sampler(task, reference)
            .ok_or(ReplacementObjectRetirementError::UnknownReference)?;
        let descriptor = self
            .execution
            .active
            .samplers
            .retire(sampler)
            .map_err(ReplacementObjectRetirementError::State)?;
        self.session.vulkan.samplers().retire_dynamic(sampler);
        let released = self
            .execution
            .active
            .namespaces
            .release_sampler(task, reference);
        debug_assert!(released);
        Ok(descriptor)
    }

