    #[cfg(test)]
    fn install_compute_translation(
        &self,
        pipeline: ResourceId<ComputePipelineObject>,
        local_size: [u32; 3],
        translation: Arc<dyn ComputeTranslation>,
    ) {
        let PipelineReadiness::Ready(family) = self
            .compute
            .lock()
            .readiness_snapshot(pipeline)
            .expect("the declared test pipeline exists")
        else {
            panic!("the declared test pipeline is ready")
        };
        if let Some(static_length) = translation.static_threadgroup_memory_length() {
            let contract = self
                .compute_contract(pipeline)
                .expect("the declared test pipeline retains its contract");
            let limits = self.vulkan.compute_info_limits();
            *family.native.info.lock() = Some(reims_vgpu_core::ComputePipelineStateInfo {
                max_total_threads_per_threadgroup: u64::from(
                    contract
                        .max_total_threads_per_threadgroup
                        .map_or(limits.max_total_threads_per_threadgroup, |declared| {
                            declared.min(limits.max_total_threads_per_threadgroup)
                        }),
                ),
                thread_execution_width: u64::from(limits.thread_execution_width),
                static_threadgroup_memory_length: static_length,
                supports_indirect_command_buffers: contract.supports_indirect_command_buffers,
            });
        }
        family
            .native
            .translations
            .lock()
            .insert(local_size, ComputeTranslationState::Ready(translation));
    }

    fn compute_translation_snapshot(
        &self,
        pipeline: ResourceId<ComputePipelineObject>,
        local_size: [u32; 3],
        pipeline_ref: u32,
    ) -> Result<Arc<dyn ComputeTranslation>, ReplacementComputeTranslationAvailability> {
        let family = match self
            .compute
            .lock()
            .readiness_snapshot(pipeline)
            .map_err(ReplacementComputeTranslationAvailability::Lifecycle)?
        {
            PipelineReadiness::Ready(ready) => ready,
            PipelineReadiness::Pending => {
                return Err(ReplacementComputeTranslationAvailability::Pending)
            }
            PipelineReadiness::Refused(reason) => {
                return Err(ReplacementComputeTranslationAvailability::Refused(
                    reason.reason,
                ))
            }
        };
        {
            let mut translations = family.native.translations.lock();
            match translations.get(&local_size) {
                Some(ComputeTranslationState::Ready(translation)) => {
                    return Ok(Arc::clone(translation));
                }
                Some(ComputeTranslationState::Translating) => {
                    return Err(ReplacementComputeTranslationAvailability::Pending);
                }
                Some(ComputeTranslationState::Refused(reason)) => {
                    return Err(ReplacementComputeTranslationAvailability::Refused(
                        reason.clone(),
                    ));
                }
                None => {
                    translations.insert(local_size, ComputeTranslationState::Translating);
                }
            }
        }
        let contract = self
            .compute_contract(pipeline)
            .expect("a ready pipeline retains its construction contract");
        let capabilities = Arc::new(
            reims_vgpu_protocol::StorageImageFormat::ALL
                .into_iter()
                .map(|format| {
                    (
                        format,
                        self.vulkan.runtime_storage_image_capabilities(format),
                    )
                })
                .collect::<HashMap<_, _>>(),
        );
        if let Err(reason) = self.pipeline_workers.submit(move |worker| {
            let result = translate_compute_pipeline_contract(
                &contract,
                local_size,
                pipeline_ref,
                capabilities,
            );
            let _ = worker
                .completions
                .send(PipelineCompileCompletion::ComputeTranslation {
                    pipeline,
                    local_size,
                    result,
                });
        }) {
            family.native.translations.lock().insert(
                local_size,
                ComputeTranslationState::Refused(ReplacementPipelineRefusal::TranslationWorker(
                    reason,
                )),
            );
            return Err(ReplacementComputeTranslationAvailability::Refused(
                ReplacementPipelineRefusal::TranslationWorker(reason),
            ));
        }
        Err(ReplacementComputeTranslationAvailability::Pending)
    }

    fn compute_info_snapshot(
        &self,
        pipeline: ResourceId<ComputePipelineObject>,
    ) -> Option<reims_vgpu_core::ComputePipelineStateInfo> {
        match self.compute.lock().readiness_snapshot(pipeline).ok()? {
            PipelineReadiness::Ready(ready) => *ready.native.info.lock(),
            PipelineReadiness::Pending | PipelineReadiness::Refused(_) => None,
        }
    }

    fn render_semantic_snapshot(
        &self,
        pipeline: ResourceId<RenderPipelineObject>,
    ) -> Result<Arc<ResolvedRenderPipeline>, ReplacementRenderSemanticAvailability> {
        match self
            .render
            .lock()
            .readiness_snapshot(pipeline)
            .map_err(ReplacementRenderSemanticAvailability::Lifecycle)?
        {
            PipelineReadiness::Ready(ready) => Ok(Arc::clone(&ready.native.semantic)),
            PipelineReadiness::Pending => Err(ReplacementRenderSemanticAvailability::Pending),
            PipelineReadiness::Refused(reason) => Err(
                ReplacementRenderSemanticAvailability::Refused(reason.reason),
            ),
        }
    }

    fn render_info_snapshot(
        &self,
        pipeline: ResourceId<RenderPipelineObject>,
    ) -> Option<reims_vgpu_core::RenderPipelineStateInfo> {
        match self.render.lock().readiness_snapshot(pipeline).ok()? {
            PipelineReadiness::Ready(ready) => ready.native.info,
            PipelineReadiness::Pending | PipelineReadiness::Refused(_) => None,
        }
    }

    /// Resolve or admit the exact render variant needed by one immutable draw.
    /// A returned compile job is intended for the fixed CPU executor; this
    /// method itself performs no translation, Vulkan creation, or wait.
    pub fn render_variant(
        &self,
        operation: &ResolvedRenderDispatch,
        transaction: TransactionId,
    ) -> Result<RenderVariantReadiness, RenderVariantAcquireError> {
        let family = match self
            .render_readiness(operation.pipeline, transaction)
            .map_err(RenderVariantAcquireError::Pipeline)?
        {
            PipelineReadiness::Ready(family) => family,
            PipelineReadiness::Pending => return Ok(RenderVariantReadiness::PipelinePending),
            PipelineReadiness::Refused(reason) => {
                return Ok(RenderVariantReadiness::PipelineRefused(reason.reason));
            }
        };
        let plan = resolve_render_pipeline_plan(
            operation,
            family.native.semantic.desc.effective_raster_sample_count(),
        )
        .map_err(RenderVariantAcquireError::Plan)?;
        let key = plan.variant_key();
        match family.native.variants.readiness_or_begin(key, transaction) {
            PipelineVariantAdmission::Ready(native) => {
                Ok(RenderVariantReadiness::Ready(ReadyPipelineLease {
                    pipeline: family.pipeline,
                    native_object: family.native_object.clone(),
                    native,
                }))
            }
            PipelineVariantAdmission::Pending => Ok(RenderVariantReadiness::Pending),
            PipelineVariantAdmission::Refused(reason) => {
                Ok(RenderVariantReadiness::Refused(reason))
            }
            PipelineVariantAdmission::Compile(job) => Ok(RenderVariantReadiness::Compile {
                family,
                job,
                plan: Box::new(plan),
            }),
        }
    }

    pub fn schedule_render_variant(
        &self,
        transaction: TransactionId,
        family: ReadyPipelineLease<RenderPipelineObject, PublishedRenderPipeline>,
        job: PipelineVariantCompileJob<ReplacementRenderPipelineVariantKey>,
        plan: ReplacementRenderPipelinePlan,
        depth_stencil: Option<DepthStencilDescriptor>,
    ) -> Result<RecordingWorkerId, FixedExecutorError> {
        self.pipeline_workers
            .submit_transaction(transaction, move |worker| {
                let result = worker.render.compile_family_job(
                    &family.native.variants,
                    job,
                    &family.native.semantic,
                    plan,
                    depth_stencil.as_ref(),
                );
                let (waiters, outcome) = match result {
                    Ok(publication) => (publication.waiters, RenderVariantCompileOutcome::Ready),
                    Err(ReplacementRenderFamilyCompileError::Refused { reason, waiters }) => {
                        (waiters, RenderVariantCompileOutcome::Refused(reason))
                    }
                    Err(ReplacementRenderFamilyCompileError::Lifecycle(reason)) => (
                        Box::default(),
                        RenderVariantCompileOutcome::Lifecycle(reason),
                    ),
                };
                let _ = worker.completions.send(PipelineCompileCompletion::Render {
                    pipeline: family.pipeline,
                    waiters,
                    outcome,
                });
            })
    }

    /// Resolve or admit the exact compute variant needed by one immutable
    /// dispatch. The prepared program is retained by a compile result until a
    /// worker consumes it, so asynchronous publication cannot outlive its
    /// translated shader lifetime.
    fn compute_variant_with_program(
        &self,
        operation: &ResolvedComputeDispatch,
        transaction: TransactionId,
        program: PreparedComputeProgram,
    ) -> Result<ComputeVariantReadiness, ComputeVariantAcquireError> {
        let required_dispatch = operation.launch.program_dispatch_contract();
        if program.dispatch != required_dispatch {
            return Err(ComputeVariantAcquireError::ProgramDispatchContract {
                required: required_dispatch,
                prepared: program.dispatch,
            });
        }
        let family = match self
            .compute_readiness(operation.pipeline, transaction)
            .map_err(ComputeVariantAcquireError::Pipeline)?
        {
            PipelineReadiness::Ready(family) => family,
            PipelineReadiness::Pending => return Ok(ComputeVariantReadiness::PipelinePending),
            PipelineReadiness::Refused(reason) => {
                return Ok(ComputeVariantReadiness::PipelineRefused(reason.reason));
            }
        };
        let plan = resolve_compute_pipeline_plan(operation, program.stage.clone())
            .map_err(ComputeVariantAcquireError::Plan)?;
        let key = plan.variant_key();
        match family.native.variants.readiness_or_begin(key, transaction) {
            PipelineVariantAdmission::Ready(native) => {
                Ok(ComputeVariantReadiness::Ready(ReadyPipelineLease {
                    pipeline: family.pipeline,
                    native_object: family.native_object.clone(),
                    native,
                }))
            }
            PipelineVariantAdmission::Pending => Ok(ComputeVariantReadiness::Pending),
            PipelineVariantAdmission::Refused(reason) => {
                Ok(ComputeVariantReadiness::Refused(reason))
            }
            PipelineVariantAdmission::Compile(job) => Ok(ComputeVariantReadiness::Compile {
                family,
                job,
                plan,
                program,
            }),
        }
    }

    /// Resolve native compute specialization only from the immutable semantic
    /// operation and its pipeline's retained translation. Packet ingress cannot
    /// supply a separately prepared shader program through this seam.
    pub fn compute_variant_for_operation(
        &self,
        operation: &ResolvedComputeDispatch,
        transaction: TransactionId,
    ) -> Result<ComputeVariantReadiness, ReplacementComputeProgramPreparationError> {
        let translation = self
            .compute_translation_snapshot(
                operation.pipeline,
                operation.launch.threads_per_threadgroup(),
                operation.pipeline.index(),
            )
            .map_err(ReplacementComputeProgramPreparationError::Translation)?;
        let requests = compute_storage_image_requests(operation)?;
        let samplers = operation
            .samplers
            .iter()
            .map(|binding| binding.sampler)
            .collect::<Vec<_>>();
        let program = translation
            .prepare_program(
                &requests,
                &samplers,
                operation.launch.program_dispatch_contract(),
            )
            .map_err(ReplacementComputeProgramPreparationError::Program)?;
        self.compute_variant_with_program(operation, transaction, program)
            .map_err(ReplacementComputeProgramPreparationError::Variant)
    }

    pub fn schedule_compute_variant(
        &self,
        transaction: TransactionId,
        family: ReadyPipelineLease<ComputePipelineObject, PublishedComputePipeline>,
        job: PipelineVariantCompileJob<ReplacementComputePipelineVariantKey>,
        plan: ReplacementComputePipelinePlan,
        program: PreparedComputeProgram,
    ) -> Result<RecordingWorkerId, FixedExecutorError> {
        self.pipeline_workers
            .submit_transaction(transaction, move |worker| {
                let _program = program;
                let result = worker
                    .compute
                    .compile_family_job(&family.native.variants, job, plan);
                let (waiters, outcome) = match result {
                    Ok(publication) => (publication.waiters, ComputeVariantCompileOutcome::Ready),
                    Err(ReplacementComputeFamilyCompileError::Refused { reason, waiters }) => {
                        (waiters, ComputeVariantCompileOutcome::Refused(reason))
                    }
                    Err(ReplacementComputeFamilyCompileError::Lifecycle(reason)) => (
                        Box::default(),
                        ComputeVariantCompileOutcome::Lifecycle(reason),
                    ),
                };
                let _ = worker.completions.send(PipelineCompileCompletion::Compute {
                    pipeline: family.pipeline,
                    waiters,
                    outcome,
                });
            })
    }

    pub fn take_pipeline_compile_completions(&self) -> Vec<PipelineCompileCompletion> {
        self.pipeline_completions
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .try_iter()
            .collect()
    }

    /// Publish completed translation flights and observe native-variant worker
    /// completions. The variant family itself is published by its worker before
    /// the completion record becomes visible.
    pub fn progress_pipeline_completions(&self) -> usize {
        let completions = self.take_pipeline_compile_completions();
        let count = completions.len();
        for completion in completions {
            let publication = match completion {
                PipelineCompileCompletion::RenderTranslation { job, result } => match *result {
                    Ok(translated) => self.publish_render_translation_owned(job, translated),
                    Err(reason) => self.refuse_render_translation(job, reason),
                },
                PipelineCompileCompletion::Render { .. }
                | PipelineCompileCompletion::Compute { .. } => continue,
                PipelineCompileCompletion::ComputeTranslation {
                    pipeline,
                    local_size,
                    result,
                } => {
                    let readiness = self.compute.lock().readiness_snapshot(pipeline);
                    let Ok(PipelineReadiness::Ready(family)) = readiness else {
                        continue;
                    };
                    let state = match result {
                        Ok(translation) => {
                            let limits = self.vulkan.compute_info_limits();
                            let contract = self
                                .compute_contract(pipeline)
                                .expect("a ready pipeline retains its contract");
                            if let Some(static_length) =
                                translation.static_threadgroup_memory_length()
                            {
                                *family.native.info.lock() =
                                    Some(reims_vgpu_core::ComputePipelineStateInfo {
                                        max_total_threads_per_threadgroup: u64::from(
                                            contract.max_total_threads_per_threadgroup.map_or(
                                                limits.max_total_threads_per_threadgroup,
                                                |declared| {
                                                    declared.min(
                                                        limits.max_total_threads_per_threadgroup,
                                                    )
                                                },
                                            ),
                                        ),
                                        thread_execution_width: u64::from(
                                            limits.thread_execution_width,
                                        ),
                                        static_threadgroup_memory_length: static_length,
                                        supports_indirect_command_buffers: contract
                                            .supports_indirect_command_buffers,
                                    });
                            }
                            ComputeTranslationState::Ready(translation)
                        }
                        Err(reason) => ComputeTranslationState::Refused(
                            ReplacementPipelineRefusal::ComputeTranslation(reason),
                        ),
                    };
                    family.native.translations.lock().insert(local_size, state);
                    continue;
                }
            };
            if let Err(reason) = publication {
                crate::observe::fail(format!(
                    "replacement_pipeline_completion_refused reason={reason:?}"
                ));
            }
        }
        count
    }

    pub fn install_pipeline_wake(&self, wake: WorkerWake) -> Result<(), PipelineWakeInstallError> {
        self.pipeline_wake.install(wake)
    }

    #[cfg(test)]
    fn wait_pipeline_compile_completion(&self) -> PipelineCompileCompletion {
        self.pipeline_completions
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .recv()
            .expect("pipeline worker completion stream remains live with the session")
    }

