    #[cfg(feature = "host-window")]
    #[test]
    fn window_stream_accepts_only_monotonic_authoritative_swapchain_snapshots() {
        let surface = reims_vgpu_protocol::SurfaceId::new(3);
        let mut streams = BTreeMap::new();
        let first = reims_vgpu_core::SwapchainState {
            generation: reims_vgpu_protocol::SwapchainGenerationId::new(7),
            image_count: 2,
        };
        synchronize_present_stream(&mut streams, surface, first).unwrap();
        synchronize_present_stream(&mut streams, surface, first).unwrap();

        let replacement = reims_vgpu_core::SwapchainState {
            generation: reims_vgpu_protocol::SwapchainGenerationId::new(8),
            image_count: 3,
        };
        synchronize_present_stream(&mut streams, surface, replacement).unwrap();
        assert_eq!(streams[&surface].current(), replacement);

        let aliased = reims_vgpu_core::SwapchainState {
            generation: replacement.generation,
            image_count: 4,
        };
        assert_eq!(
            synchronize_present_stream(&mut streams, surface, aliased),
            Err((replacement, aliased))
        );
        assert_eq!(streams[&surface].current(), replacement);
        assert_eq!(
            synchronize_present_stream(&mut streams, surface, first),
            Err((replacement, first))
        );
    }

