    #[test]
    fn present_notification_stores_pending_before_it_owes_the_irq() {
        let mut host = crate::runtime::host::FakeHost::new();
        let page = reims_vgpu_core::DisplaySharedPage {
            gpa: 0x4000,
            display_index: 2,
        };
        host.map_range(page.gpa, 0x1000, 0);
        let interrupt_status = std::sync::atomic::AtomicU32::new(0);
        apply_display_present_notification(
            &mut host,
            &interrupt_status,
            reims_vgpu_core::DisplayPresentNotification::Deliver {
                page,
                pending: reims_vgpu_core::DISPLAY_PRESENT_EVENT_MASK,
                interrupt_bit: 1 << 2,
                stale_online_removed: false,
            },
        )
        .unwrap();
        assert_eq!(
            host.get_u32(page.gpa + reims_vgpu_core::DISPLAY_SHARED_PENDING_OFFSET),
            reims_vgpu_core::DISPLAY_PRESENT_EVENT_MASK
        );
        assert_eq!(
            interrupt_status.load(std::sync::atomic::Ordering::Acquire),
            1 << 2
        );
        assert_eq!(
            host.action_count(crate::runtime::host::HostActionKind::IrqGfxPulse),
            1
        );

        let mut refused_host = crate::runtime::host::FakeHost::new();
        let refused_status = std::sync::atomic::AtomicU32::new(0);
        let overflow_page = reims_vgpu_core::DisplaySharedPage {
            gpa: u64::MAX,
            display_index: 2,
        };
        assert_eq!(
            apply_display_present_notification(
                &mut refused_host,
                &refused_status,
                reims_vgpu_core::DisplayPresentNotification::Deliver {
                    page: overflow_page,
                    pending: reims_vgpu_core::DISPLAY_PRESENT_EVENT_MASK,
                    interrupt_bit: 1 << 2,
                    stale_online_removed: false,
                },
            ),
            Err(crate::runtime::host::MemError::Overflow)
        );
        assert_eq!(refused_status.load(std::sync::atomic::Ordering::Acquire), 0);
        assert_eq!(
            refused_host.action_count(crate::runtime::host::HostActionKind::IrqGfxPulse),
            0
        );
    }

    #[derive(Default)]
    struct ReplacementMapperMemory(BTreeMap<u64, u8>);

    impl ReplacementMapperMemory {
        fn write(&mut self, address: u64, bytes: &[u8]) {
            self.0.extend(
                bytes
                    .iter()
                    .enumerate()
                    .map(|(offset, byte)| (address + u64::try_from(offset).unwrap(), *byte)),
            );
        }

        fn for_capture(capture: reims_vgpu_core::MapperCapture, mapping_id: u32) -> Self {
            use reims_vgpu_paging::mapper as paging;
            let descriptor_kva = capture.mapping_internal + 0x1000;
            let page_owner = capture.mapping_internal + 0x2000;
            let page_table = capture.mapping_internal + 0x3000;
            let mut memory = Self::default();
            memory.write(
                capture.mapping_internal + paging::MAPPING_INTERNAL_BACKPTR,
                &capture.mapper_device_kva.to_le_bytes(),
            );
            memory.write(
                capture.mapping_internal + paging::MAPPING_INTERNAL_ID,
                &mapping_id.to_le_bytes(),
            );
            memory.write(
                capture.mapping_internal + paging::MAPPING_INTERNAL_DESC_PTR,
                &descriptor_kva.to_le_bytes(),
            );
            memory.write(
                capture.mapping_internal + paging::MAPPING_INTERNAL_SIZE,
                &paging::MAPPING_INTERNAL_EXPECTED_SIZE.to_le_bytes(),
            );
            memory.write(
                capture.mapping_internal + paging::MAPPING_INTERNAL_PAGE_FIELD_48,
                &page_owner.to_le_bytes(),
            );
            memory.write(
                capture.mapping_internal + paging::MAPPING_INTERNAL_PAGE_FIELD_50,
                &(capture.mapping_internal + 0x4000).to_le_bytes(),
            );
            memory.write(
                capture.mapping_internal + paging::MAPPING_INTERNAL_PAGE_COUNT,
                &2u64.to_le_bytes(),
            );
            memory.write(
                page_owner + paging::MAPPING_PAGE_TABLE_FROM_F48,
                &page_table.to_le_bytes(),
            );
            memory.write(page_table, &5u32.to_le_bytes());
            memory.write(page_table + 4, &9u32.to_le_bytes());
            let mut descriptor = [0u8; reims_vgpu_protocol::DEVICE_DESC_LEN];
            descriptor[reims_vgpu_protocol::DEVICE_DESC_PIXEL_FORMAT..][..4].copy_from_slice(
                &u32::from(reims_vgpu_protocol::metal_pixel::MTL_FORMAT_BGRA8_UNORM).to_le_bytes(),
            );
            descriptor[reims_vgpu_protocol::DEVICE_DESC_ALLOC_SIZE..][..4]
                .copy_from_slice(&0x2000u32.to_le_bytes());
            descriptor[reims_vgpu_protocol::DEVICE_DESC_DIMS..][..8]
                .copy_from_slice(&((64u64 << 8) | (32u64 << 40)).to_le_bytes());
            descriptor[reims_vgpu_protocol::DEVICE_DESC_BPR..][..4]
                .copy_from_slice(&256u32.to_le_bytes());
            descriptor[reims_vgpu_protocol::DEVICE_DESC_BPE..][..2]
                .copy_from_slice(&4u16.to_le_bytes());
            memory.write(descriptor_kva, &descriptor);
            memory
        }
    }

    impl reims_vgpu_paging::mapper::PagesMemory for ReplacementMapperMemory {
        fn read(&self, address: u64, dst: &mut [u8]) -> bool {
            let Some(bytes) = (0..dst.len())
                .map(|offset| {
                    self.0
                        .get(&(address + u64::try_from(offset).unwrap()))
                        .copied()
                })
                .collect::<Option<Vec<_>>>()
            else {
                return false;
            };
            dst.copy_from_slice(&bytes);
            true
        }
    }

    fn replacement_packet(
        opcode: u16,
        payload: impl Into<Vec<u8>>,
        completion_stamp: u32,
    ) -> crate::runtime::fifo_packet::Packet {
        let payload = payload.into();
        let total_size = crate::model::PACKET_HEADER_LEN + payload.len() as u32;
        crate::runtime::fifo_packet::Packet {
            opcode,
            stamp_waits: Vec::new(),
            total_size,
            completion_stamp,
            payload,
            next_head: total_size,
        }
    }

    #[test]
    fn composition_resource_preparation_retains_owner_after_family_refusal() {
        let mut owners = ReplacementExecutionOwners::<()>::new(
            reims_vgpu_core::SessionGeneration::new(SessionGenerationId::new(1)),
            VulkanDeviceEpochId::new(1),
            1,
        )
        .unwrap();
        let operation = reims_vgpu_core::ResolvedBlit::Fill {
            destination: reims_vgpu_core::ResolvedBufferRange {
                resource: ResourceId::new(7, 1),
                storage: reims_vgpu_protocol::BackingId::new(9),
                region: reims_vgpu_core::LinearRange::new(0, 16).unwrap(),
                address: reims_vgpu_protocol::GuestVirtualAddress::new(0x1000),
                length: reims_vgpu_protocol::ByteLength::new(16),
            },
            pattern: reims_vgpu_core::BufferFillPattern::Byte(0x5a),
        };
        let mut preparation = owners.begin_exec_resource_preparation(TransactionId::new(3));
        let failure = preparation
            .prepare_buffer_blit(SubmissionId::new(4), 0, operation.clone())
            .unwrap_err();
        let reims_vgpu_core::ExecResourcePreparationStepFailure::Preparation(failure) = *failure
        else {
            panic!("an unused position cannot be occupied")
        };
        assert_eq!(failure.operation, operation);

        let cancelled = preparation.cancel().unwrap();
        assert!(cancelled.buffer_blits.is_empty());
        assert!(cancelled.resources.is_empty());
    }

    #[test]
    fn composition_prepares_resource_states_inside_the_exec_owner() {
        type Operation = reims_vgpu_core::ResolvedOperation<
            ResolvedRenderDispatch,
            ResolvedComputeDispatch,
            reims_vgpu_core::ResolvedInfoOperation,
            reims_vgpu_core::ResolvedIndirectCommand,
            (),
        >;
        let mut owners = ReplacementExecutionOwners::<()>::new(
            reims_vgpu_core::SessionGeneration::new(SessionGenerationId::new(1)),
            VulkanDeviceEpochId::new(1),
            1,
        )
        .unwrap();
        let reims_vgpu_core::ResourceLifecycleEffect::BackingCreated(backing) = owners
            .resources_mut()
            .apply(reims_vgpu_core::ResolvedResourceLifecycle::CreateBacking {
                backing: reims_vgpu_core::StorageBacking::Dedicated,
                regions: Box::new([reims_vgpu_core::BackingRegion::Whole]),
            })
            .unwrap()
        else {
            unreachable!()
        };
        let exec = reims_vgpu_core::ExecTransaction::<Operation> {
            identity: reims_vgpu_protocol::SubmissionIdentity {
                id: SubmissionId::new(4),
                task: reims_vgpu_protocol::TaskId::new(1),
            },
            prologue: reims_vgpu_core::ExecPrologue::resource_states([
                reims_vgpu_core::ResolvedResourceState {
                    resource: None,
                    mappings: Box::new([]),
                    targets: Box::new([reims_vgpu_core::ResolvedResourceStateTarget {
                        backing,
                        regions: Box::new([reims_vgpu_core::BackingRegion::Whole]),
                    }]),
                    ops: reims_vgpu_protocol::ResourceValidityOps {
                        set_guest_valid: 1,
                        ..reims_vgpu_protocol::ResourceValidityOps::default()
                    },
                },
            ]),
            streams: Box::new([reims_vgpu_core::ResolvedExecStream {
                stream_index: 0,
                segments: Box::new([reims_vgpu_core::ResolvedExecSegment {
                    boundary: reims_vgpu_protocol::SegmentBoundary {
                        stream_index: 0,
                        index: 0,
                        kind: reims_vgpu_protocol::SegmentKind::Blit,
                        continues_previous: false,
                        continues_next: false,
                    },
                    operations: Box::new([]),
                }]),
            }]),
            accesses: Box::new([]),
        };
        let channel = reims_vgpu_protocol::ChannelId::new(1);
        owners.runtime_mut().define_channel(channel).unwrap();
        let admitted_exec = owners
            .runtime_mut()
            .admit_exec_operations(
                channel,
                Box::<[reims_vgpu_core::ResolvedTransactionPrerequisite]>::default(),
                Some(reims_vgpu_core::CompletionStamp::new(channel.get(), 1)),
                exec,
            )
            .unwrap();
        let transaction = admitted_exec.transaction.id;
        let admitted = admitted_exec.resource_states().clone();
        let reims_vgpu_core::DeviceTransactionPayload::Exec(exec) =
            admitted_exec.transaction.payload
        else {
            unreachable!()
        };
        let mut preparation = owners.begin_exec_resource_preparation(transaction);
        preparation
            .prepare_resource_states(admitted, exec.identity.id, |_, _| {
                reims_vgpu_core::ValidityRepresentations::default()
            })
            .unwrap();

        let prepared = preparation.finish(&exec, 0).unwrap();
        assert_eq!(prepared.transaction(), transaction);
        assert_eq!(
            prepared
                .inputs()
                .resource_states
                .as_ref()
                .unwrap()
                .states()
                .len(),
            1
        );
    }

    #[test]
    fn execution_owner_aggregates_one_exact_generation_and_epoch() {
        let first_generation = reims_vgpu_core::SessionGeneration::new(SessionGenerationId::new(4));
        let mut first = ReplacementExecutionOwners::<()>::new(
            first_generation.clone(),
            VulkanDeviceEpochId::new(8),
            2,
        )
        .unwrap();
        let second = ReplacementExecutionOwners::<()>::new(
            reims_vgpu_core::SessionGeneration::new(SessionGenerationId::new(5)),
            VulkanDeviceEpochId::new(9),
            1,
        )
        .unwrap();
        first
            .runtime_mut()
            .define_channel(reims_vgpu_protocol::ChannelId::new(3))
            .unwrap();
        let old = first
            .runtime_mut()
            .admit_resolved(
                reims_vgpu_protocol::ChannelId::new(3),
                Box::<[reims_vgpu_core::ResolvedTransactionPrerequisite]>::default(),
                None,
                reims_vgpu_core::DeviceTransactionPayload::<(), (), (), (), ()>::Control(()),
            )
            .unwrap();
        assert_eq!(
            first.runtime().session_generation(),
            SessionGenerationId::new(4)
        );
        assert_eq!(
            second.runtime().session_generation(),
            SessionGenerationId::new(5)
        );
        assert!(first
            .resources()
            .graph()
            .storage(reims_vgpu_protocol::BackingId::new(1))
            .is_none());
        assert!(second
            .resources()
            .graph()
            .storage(reims_vgpu_protocol::BackingId::new(1))
            .is_none());
        let old_point = {
            let native = first.native_mut();
            native
                .assign_recording(reims_vgpu_core::TransactionRecordingPlan {
                    transaction: old.id,
                    domain: reims_vgpu_protocol::SubmissionDomainId::new(3),
                    continuation_predecessor: None,
                })
                .unwrap();
            let plan = native
                .queue_candidate(
                    old.id,
                    Box::<[(TransactionId, reims_vgpu_core::WaitDependencyCause)]>::default(),
                )
                .unwrap()
                .pop()
                .unwrap();
            let prepared = native
                .prepare(
                    plan,
                    QueueOwnerId::new(7),
                    SessionGenerationId::new(4),
                    ResolvedReplayCompletion {
                        semantic: (),
                        resources: Box::new([]),
                    },
                )
                .unwrap();
            let point = prepared.point();
            native.cancel_prepared(prepared).unwrap();
            point
        };

        assert_eq!(
            first
                .reset_generation(reims_vgpu_core::SessionGeneration::new(
                    SessionGenerationId::new(6),
                ))
                .unwrap(),
            SessionGenerationId::new(4)
        );
        assert!(!first_generation.is_accepting());
        assert_eq!(first.retired_generation_count(), 1);
        assert!(first
            .runtime_for_generation_mut(SessionGenerationId::new(4))
            .is_some());
        first
            .runtime_mut()
            .define_channel(reims_vgpu_protocol::ChannelId::new(3))
            .unwrap();
        let new = first
            .runtime_mut()
            .admit_resolved(
                reims_vgpu_protocol::ChannelId::new(3),
                Box::<[reims_vgpu_core::ResolvedTransactionPrerequisite]>::default(),
                None,
                reims_vgpu_core::DeviceTransactionPayload::<(), (), (), (), ()>::Control(()),
            )
            .unwrap();
        assert_eq!(old.id, TransactionId::new(1));
        assert_eq!(new.id, TransactionId::new(2));
        let new_point = {
            let native = first.native_mut();
            native
                .assign_recording(reims_vgpu_core::TransactionRecordingPlan {
                    transaction: new.id,
                    domain: reims_vgpu_protocol::SubmissionDomainId::new(3),
                    continuation_predecessor: None,
                })
                .unwrap();
            let plan = native
                .queue_candidate(
                    new.id,
                    Box::<[(TransactionId, reims_vgpu_core::WaitDependencyCause)]>::default(),
                )
                .unwrap()
                .pop()
                .unwrap();
            let prepared = native
                .prepare(
                    plan,
                    QueueOwnerId::new(7),
                    SessionGenerationId::new(6),
                    ResolvedReplayCompletion {
                        semantic: (),
                        resources: Box::new([]),
                    },
                )
                .unwrap();
            let point = prepared.point();
            native.cancel_prepared(prepared).unwrap();
            point
        };
        assert_eq!(old_point.value.get(), 1);
        assert_eq!(new_point.value.get(), 2);
    }

    #[test]
    fn reset_routes_submitted_completion_to_the_closed_generation() {
        use reims_vgpu_protocol::{
            ChannelId, SegmentBoundary, SegmentKind, SubmissionId, SubmissionIdentity, TaskId,
        };

        let mut owners = ReplacementExecutionOwners::<()>::new(
            reims_vgpu_core::SessionGeneration::new(SessionGenerationId::new(1)),
            VulkanDeviceEpochId::new(3),
            1,
        )
        .unwrap();
        let channel = ChannelId::new(2);
        owners.runtime_mut().define_channel(channel).unwrap();
        let transaction = owners
            .runtime_mut()
            .admit_resolved(
                channel,
                Box::<[reims_vgpu_core::ResolvedTransactionPrerequisite]>::default(),
                Some(reims_vgpu_core::CompletionStamp::new(channel.get(), 1)),
                reims_vgpu_core::DeviceTransactionPayload::<(), (), (), (), ()>::Exec(
                    reims_vgpu_core::ExecTransaction {
                        identity: SubmissionIdentity {
                            id: SubmissionId::new(1),
                            task: TaskId::new(1),
                        },
                        prologue: reims_vgpu_core::ExecPrologue::default(),
                        streams: Box::new([reims_vgpu_core::ResolvedExecStream {
                            stream_index: 0,
                            segments: Box::new([reims_vgpu_core::ResolvedExecSegment {
                                boundary: SegmentBoundary {
                                    stream_index: 0,
                                    index: 0,
                                    kind: SegmentKind::Render,
                                    continues_previous: false,
                                    continues_next: false,
                                },
                                operations: Box::new([]),
                            }]),
                        }]),
                        accesses: Box::new([]),
                    },
                ),
            )
            .unwrap();
        let recording = owners.runtime().recording_plan(transaction.id).unwrap();
        owners.native_mut().assign_recording(recording).unwrap();
        owners.runtime_mut().recorded(transaction.id).unwrap();
        assert_eq!(
            owners.runtime_mut().take_submission_ready()[0].transaction,
            transaction.id
        );
        let native_plan = owners
            .native_mut()
            .queue_candidate(
                transaction.id,
                Box::<[(TransactionId, reims_vgpu_core::WaitDependencyCause)]>::default(),
            )
            .unwrap()
            .pop()
            .unwrap();
        let prepared = owners
            .native_mut()
            .prepare(
                native_plan,
                QueueOwnerId::new(4),
                SessionGenerationId::new(1),
                ResolvedReplayCompletion {
                    semantic: (),
                    resources: Box::new([]),
                },
            )
            .unwrap();
        let point = prepared.point();
        owners.native_mut().accepted(prepared).unwrap();
        owners.runtime_mut().submitted(transaction.id).unwrap();

        owners
            .reset_generation(reims_vgpu_core::SessionGeneration::new(
                SessionGenerationId::new(2),
            ))
            .unwrap();
        let fact = owners
            .native_mut()
            .advance(point.queue, point.value)
            .unwrap()
            .pop()
            .unwrap();
        let fact = reims_vgpu_core::CompletionFact {
            transaction: fact.transaction,
            session_generation: fact.session_generation,
            evidence: fact.evidence,
            semantic: fact.semantic.semantic,
        };
        let committed = owners.commit_completion(fact).unwrap();
        assert_eq!(committed.len(), 1);
        assert_eq!(committed[0].transaction, transaction.id);
        assert_eq!(owners.retired_generation_count(), 1);
        owners
            .retire_transaction(SessionGenerationId::new(1), transaction.id)
            .unwrap();
        assert_eq!(owners.retired_generation_count(), 0);
        assert_eq!(
            owners.runtime().session_generation(),
            SessionGenerationId::new(2)
        );
    }

