    #[test]
    fn compute_control_flow_refusal_retains_exact_predicate_buffer_and_operands() {
        let Some(mut runtime) = runtime_session() else {
            return;
        };
        let task = reims_vgpu_protocol::TaskId::new(34);
        crate::runtime::replacement_object_lifecycle::apply_replacement_linear_resource(
            &mut runtime,
            12,
            task,
            61,
            reims_vgpu_protocol::ResourceDescriptor::Buffer(
                reims_vgpu_protocol::BufferDescriptor {
                    allocation_size: 0x100,
                    handle: 0x5000,
                    ..Default::default()
                },
            ),
        )
        .unwrap();
        let predicate_buffer = runtime
            .resolve_buffer_range(
                task,
                reims_vgpu_protocol::ObjectTableRef::new(61),
                12,
                core::mem::size_of::<u32>() as u64,
            )
            .unwrap();
        let mut state =
            crate::runtime::replacement_exec_decode::ReplacementRecordProjectionState::default();
        state.encoder_boundary(reims_vgpu_core::EncoderBoundary::Begin(
            reims_vgpu_protocol::SegmentKind::Compute,
        ));
        let opcode = reims_vgpu_wire::ops::compute::OPCODE_START_IF;
        let record = crate::runtime::replacement_exec_decode::DecodedReplacementRecord::Compute(
            Box::new(crate::runtime::decode::compute::Command {
                kind: crate::runtime::decode::compute::Kind::ControlStartIf,
                opcode,
                condition_buffer_ref: 61,
                condition_buffer_offset: 12,
                condition_comparison: 6,
                condition_reference_value: 0x1234_5678,
                ..Default::default()
            }),
        );
        assert_eq!(
            crate::runtime::replacement_exec_decode::project_replacement_record::<(), ()>(
                &mut runtime,
                task,
                &mut state,
                &record,
            ),
            Err(
                crate::runtime::replacement_exec_decode::ReplacementOperationProjectionError::ComputeControlFlow(
                    Box::new(crate::runtime::replacement_exec_decode::ReplacementComputeControlFlowResolutionError::Unsupported {
                        kind: crate::runtime::decode::compute::Kind::ControlStartIf,
                        opcode,
                        predicate: Some(
                            crate::runtime::replacement_exec_decode::ReplacementResolvedComputeControlPredicate {
                                buffer: predicate_buffer,
                                comparison: 6,
                                reference_value: 0x1234_5678,
                            }
                        ),
                    })
                )
            )
        );

        let marker_opcode = reims_vgpu_wire::ops::compute::OPCODE_START_ELSE;
        let marker = crate::runtime::replacement_exec_decode::DecodedReplacementRecord::Compute(
            Box::new(crate::runtime::decode::compute::Command {
                kind: crate::runtime::decode::compute::Kind::ControlStartElse,
                opcode: marker_opcode,
                ..Default::default()
            }),
        );
        assert_eq!(
            crate::runtime::replacement_exec_decode::project_replacement_record::<(), ()>(
                &mut runtime,
                task,
                &mut state,
                &marker,
            ),
            Err(
                crate::runtime::replacement_exec_decode::ReplacementOperationProjectionError::ComputeControlFlow(
                    Box::new(crate::runtime::replacement_exec_decode::ReplacementComputeControlFlowResolutionError::Unsupported {
                        kind: crate::runtime::decode::compute::Kind::ControlStartElse,
                        opcode: marker_opcode,
                        predicate: None,
                    })
                )
            )
        );
    }

    #[test]
    fn tessellation_factor_buffer_state_retains_offset_and_instance_stride() {
        let Some(mut runtime) = runtime_session() else {
            return;
        };
        let task = reims_vgpu_protocol::TaskId::new(35);
        let mut state =
            crate::runtime::replacement_exec_decode::ReplacementRecordProjectionState::default();
        state.encoder_boundary(reims_vgpu_core::EncoderBoundary::Begin(
            reims_vgpu_protocol::SegmentKind::Render,
        ));
        let record = |buffer_ref| {
            crate::runtime::replacement_exec_decode::DecodedReplacementRecord::Render(Box::new(
                crate::runtime::decode::render::Command {
                    kind: crate::runtime::decode::render::Kind::SetTessellationFactorBuffer,
                    opcode: reims_vgpu_wire::ops::render::OPCODE_SET_TESSELLATION_FACTOR_BUFFER,
                    buffer_ref,
                    buffer_offset: 0x3456,
                    tessellation_factor_instance_stride: 0x4567,
                    ..Default::default()
                },
            ))
        };
        crate::runtime::replacement_exec_decode::project_replacement_record::<(), ()>(
            &mut runtime,
            task,
            &mut state,
            &record(5151),
        )
        .unwrap();
        assert_eq!(
            state.render().unwrap().tessellation_factor_buffer,
            Some(
                crate::runtime::replacement_exec_decode::ReplacementTessellationFactorBufferBinding {
                    reference: 5151,
                    offset: 0x3456,
                    instance_stride: 0x4567,
                }
            )
        );

        let patch_draw = crate::runtime::decode::render::PatchDraw::Indirect {
            control_points: 7,
            patch_indices: crate::runtime::decode::render::PatchBufferOperand {
                reference: 71,
                offset: 0x1111,
            },
            control_point_indices: Some(crate::runtime::decode::render::PatchBufferOperand {
                reference: 72,
                offset: 0x2222,
            }),
            arguments: crate::runtime::decode::render::PatchBufferOperand {
                reference: 73,
                offset: 0x3333,
            },
        };
        let patch_opcode = reims_vgpu_wire::ops::render::OPCODE_DRAW_INDEXED_PATCHES_INDIRECT;
        let patch = crate::runtime::replacement_exec_decode::DecodedReplacementRecord::Render(
            Box::new(crate::runtime::decode::render::Command {
                kind: crate::runtime::decode::render::Kind::DrawPatches,
                opcode: patch_opcode,
                patch_draw: Some(patch_draw),
                ..Default::default()
            }),
        );
        assert_eq!(
            crate::runtime::replacement_exec_decode::project_replacement_record::<(), ()>(
                &mut runtime,
                task,
                &mut state,
                &patch,
            ),
            Err(
                crate::runtime::replacement_exec_decode::ReplacementOperationProjectionError::RenderTessellation(
                    Box::new(crate::runtime::replacement_exec_decode::ReplacementRenderTessellationResolutionError::Unsupported {
                        opcode: patch_opcode,
                        draw: patch_draw,
                        factor_buffer: Some(
                            crate::runtime::replacement_exec_decode::ReplacementTessellationFactorBufferBinding {
                                reference: 5151,
                                offset: 0x3456,
                                instance_stride: 0x4567,
                            }
                        ),
                    })
                )
            )
        );

        crate::runtime::replacement_exec_decode::project_replacement_record::<(), ()>(
            &mut runtime,
            task,
            &mut state,
            &record(0),
        )
        .unwrap();
        assert_eq!(state.render().unwrap().tessellation_factor_buffer, None);
    }

    #[test]
    fn tile_records_refuse_with_the_exact_decoded_contract_and_empty_dispatch_is_a_noop() {
        let Some(mut runtime) = runtime_session() else {
            return;
        };
        let task = reims_vgpu_protocol::TaskId::new(36);
        let mut state =
            crate::runtime::replacement_exec_decode::ReplacementRecordProjectionState::default();
        state.encoder_boundary(reims_vgpu_core::EncoderBoundary::Begin(
            reims_vgpu_protocol::SegmentKind::Render,
        ));
        let record = |command| {
            crate::runtime::replacement_exec_decode::DecodedReplacementRecord::Render(Box::new(
                command,
            ))
        };

        let binding = crate::runtime::decode::render::TileBind::Sampler {
            first: 7,
            bindings: Box::new([
                crate::runtime::decode::render::TileSamplerBinding {
                    reference: 5151,
                    lod_clamp: Some((0.25f32.to_bits(), 0.75f32.to_bits())),
                },
                crate::runtime::decode::render::TileSamplerBinding {
                    reference: 5252,
                    lod_clamp: Some((0.5f32.to_bits(), 0.875f32.to_bits())),
                },
            ]),
        };
        let bind_opcode = reims_vgpu_wire::ops::tile::OPCODE_SET_TILE_SAMPLER_LOD;
        assert_eq!(
            crate::runtime::replacement_exec_decode::project_replacement_record::<(), ()>(
                &mut runtime,
                task,
                &mut state,
                &record(crate::runtime::decode::render::Command {
                    kind: crate::runtime::decode::render::Kind::TileBind,
                    opcode: bind_opcode,
                    tile_bind: Some(binding.clone()),
                    ..Default::default()
                }),
            ),
            Err(
                crate::runtime::replacement_exec_decode::ReplacementOperationProjectionError::RenderTile(
                    Box::new(crate::runtime::replacement_exec_decode::ReplacementRenderTileResolutionError::BindUnsupported {
                        opcode: bind_opcode,
                        binding,
                    })
                )
            )
        );

        let region = crate::runtime::decode::render::TileRegion {
            origin: [0x11, 0x22, 0x33],
            size: [0x44, 0x55, 0x66],
        };
        let dispatch_opcode =
            reims_vgpu_wire::ops::tile::OPCODE_DISPATCH_THREADS_PER_TILE_IN_REGION_RT_INDEX;
        assert_eq!(
            crate::runtime::replacement_exec_decode::project_replacement_record::<(), ()>(
                &mut runtime,
                task,
                &mut state,
                &record(crate::runtime::decode::render::Command {
                    kind: crate::runtime::decode::render::Kind::TileDispatch,
                    opcode: dispatch_opcode,
                    tile_threads: [8, 4, 1],
                    tile_region: Some(region),
                    tile_render_target_array_index: Some(3),
                    ..Default::default()
                }),
            ),
            Err(
                crate::runtime::replacement_exec_decode::ReplacementOperationProjectionError::RenderTile(
                    Box::new(crate::runtime::replacement_exec_decode::ReplacementRenderTileResolutionError::DispatchUnsupported {
                        opcode: dispatch_opcode,
                        threads_per_tile: [8, 4, 1],
                        region: Some(region),
                        render_target_array_index: Some(3),
                    })
                )
            )
        );

        let empty = crate::runtime::replacement_exec_decode::project_replacement_record::<(), ()>(
            &mut runtime,
            task,
            &mut state,
            &record(crate::runtime::decode::render::Command {
                kind: crate::runtime::decode::render::Kind::TileDispatch,
                opcode: reims_vgpu_wire::ops::tile::OPCODE_DISPATCH_THREADS_PER_TILE,
                tile_threads: [8, 0, 1],
                ..Default::default()
            }),
        )
        .expect("an empty tile grid is a no-op");
        assert!(empty.is_empty());

        let dimensions_opcode = reims_vgpu_wire::ops::tile::OPCODE_GET_TILE_DIMENSIONS;
        assert_eq!(
            crate::runtime::replacement_exec_decode::project_replacement_record::<(), ()>(
                &mut runtime,
                task,
                &mut state,
                &record(crate::runtime::decode::render::Command {
                    kind: crate::runtime::decode::render::Kind::TileDimensionsQuery,
                    opcode: dimensions_opcode,
                    buffer_ref: 5353,
                    buffer_offset: 0x9999,
                    ..Default::default()
                }),
            ),
            Err(
                crate::runtime::replacement_exec_decode::ReplacementOperationProjectionError::RenderTile(
                    Box::new(crate::runtime::replacement_exec_decode::ReplacementRenderTileResolutionError::DimensionsQueryUnsupported {
                        opcode: dimensions_opcode,
                        buffer_ref: 5353,
                        offset: 0x9999,
                    })
                )
            )
        );
    }

