    #[test]
    fn root_and_child_controls_share_ordered_cpu_transaction_completion() {
        let Some(mut runtime) = runtime_session() else {
            return;
        };
        let root = reims_vgpu_protocol::ChannelId::new(0);
        let child = reims_vgpu_protocol::ChannelId::new(6);
        let define_fifo = crate::runtime::replacement_fifo_control::admit_replacement_root_packet(
            &mut runtime,
            replacement_packet(
                crate::model::ROOT_OP_DEFINE_FIFO,
                child.get().to_le_bytes(),
                1,
            ),
        )
        .unwrap();
        let crate::runtime::replacement_fifo_control::ReplacementAdmittedRootPacket::Control(
            define_fifo,
        ) = define_fifo
        else {
            panic!("DefineFifo must route as a control transaction")
        };
        assert_eq!(define_fifo.transaction(), TransactionId::new(1));
        let define_fifo = runtime.apply_admitted_control(12, define_fifo).unwrap();
        assert!(matches!(
            &define_fifo.effect,
            ReplacementControlEffect::FifoDefined(defined) if *defined == child
        ));
        let root_publication = runtime.complete_control(define_fifo, ()).unwrap();
        assert_eq!(root_publication[0].transaction, TransactionId::new(1));
        assert_eq!(
            root_publication[0].completion_stamp,
            Some(reims_vgpu_core::CompletionStamp::new(root.get(), 1))
        );

        let task = reims_vgpu_protocol::TaskId::new(12);
        let define_task = runtime
            .admit_control(
                child,
                Box::default(),
                Some(reims_vgpu_core::CompletionStamp::new(child.get(), 1)),
                ReplacementControlCommand::DefineTask(
                    crate::runtime::replacement_task::DecodedReplacementTaskDefinition {
                        raw_id: task.get() << crate::model::DEFINE_TASK_ID_SHIFT,
                        task,
                        kernel_task: false,
                        length: 0x80_000,
                        directory_pfn: 13,
                    },
                ),
            )
            .unwrap();
        assert_eq!(define_task.transaction(), TransactionId::new(2));
        let define_task = runtime.apply_admitted_control(12, define_task).unwrap();
        assert!(matches!(
            &define_task.effect,
            ReplacementControlEffect::TaskDefined(ReplacementTaskDefinition {
                task: defined,
                replaced: None,
            }) if *defined == task
        ));
        let child_publication = runtime.complete_control(define_task, ()).unwrap();
        assert_eq!(child_publication[0].transaction, TransactionId::new(2));
        assert_eq!(runtime.tasks().get(task.get()).unwrap().directory_pfn, 13);

        let mut device_info_payload = [0u8; 12];
        reims_vgpu_core::endian::st32(&mut device_info_payload[0..], u32::MAX);
        reims_vgpu_core::endian::st32(&mut device_info_payload[4..], u32::MAX);
        reims_vgpu_core::endian::st32(&mut device_info_payload[8..], 19);
        let query = crate::runtime::replacement_fifo_control::admit_replacement_root_packet(
            &mut runtime,
            replacement_packet(
                crate::model::ROOT_OP_DEVICE_INFO_TAHOE,
                device_info_payload,
                2,
            ),
        )
        .unwrap();
        let crate::runtime::replacement_fifo_control::ReplacementAdmittedRootPacket::Query(query) =
            query
        else {
            panic!("device info must route as a query transaction")
        };
        assert_eq!(query.transaction(), TransactionId::new(3));
        let query = runtime.apply_admitted_query(12, u32::MAX, query).unwrap();
        assert!(matches!(
            &query.effect,
            ReplacementQueryEffect::DeviceInfo(Some(reply)) if reply.gpa == 19 << 12
        ));
        let query_publication = runtime.complete_query(query, ()).unwrap();
        assert_eq!(query_publication[0].transaction, TransactionId::new(3));
        assert_eq!(
            query_publication[0].completion_stamp,
            Some(reims_vgpu_core::CompletionStamp::new(root.get(), 2))
        );
    }

