    #[test]
    fn child_invalidation_deduplicates_aliases_and_publishes_after_validity_application() {
        let Some(mut runtime) = runtime_session() else {
            return;
        };
        let channel = reims_vgpu_protocol::ChannelId::new(4);
        let task = reims_vgpu_protocol::TaskId::new(9);
        runtime.define_channel(channel).unwrap();
        runtime.define_task(task, 0x20_000, 7).unwrap();
        let descriptor = reims_vgpu_protocol::ResourceDescriptor::Buffer(
            reims_vgpu_protocol::BufferDescriptor {
                allocation_size: 0x1000,
                handle: 0x20,
                ..Default::default()
            },
        );
        let first =
            crate::runtime::replacement_object_lifecycle::apply_replacement_linear_resource(
                &mut runtime,
                12,
                task,
                17,
                descriptor.clone(),
            )
            .unwrap();
        let second =
            crate::runtime::replacement_object_lifecycle::apply_replacement_linear_resource(
                &mut runtime,
                12,
                task,
                23,
                descriptor,
            )
            .unwrap();
        assert_eq!(first.backing, second.backing);
        let mixed = crate::runtime::decode::fifo::InvalidateResourcesCommand {
            task_id: task.get(),
            count: 2,
            records: vec![
                crate::runtime::decode::fifo::InvalidateResourceRecord {
                    object_id: 17,
                    flags: crate::runtime::decode::fifo::CHILD_INVALIDATE_PAGEON_FLAGS,
                    ops: crate::runtime::decode::fifo::InvalidateValidityOps::PAGE_ON,
                },
                crate::runtime::decode::fifo::InvalidateResourceRecord {
                    object_id: 23,
                    flags: 0,
                    ops: Default::default(),
                },
            ],
        };
        assert!(matches!(
            runtime.resolve_standalone_invalidation(&mixed),
            Err(
                ReplacementStandaloneInvalidationError::ConflictingAliasValidity {
                    position: 1,
                    ..
                }
            )
        ));
        let distinct =
            crate::runtime::replacement_object_lifecycle::apply_replacement_linear_resource(
                &mut runtime,
                12,
                task,
                31,
                reims_vgpu_protocol::ResourceDescriptor::Buffer(
                    reims_vgpu_protocol::BufferDescriptor {
                        allocation_size: 0x1000,
                        handle: 0x30,
                        ..Default::default()
                    },
                ),
            )
            .unwrap();
        assert_ne!(first.backing, distinct.backing);
        let heterogeneous = crate::runtime::decode::fifo::InvalidateResourcesCommand {
            task_id: task.get(),
            count: 2,
            records: vec![
                mixed.records[0],
                crate::runtime::decode::fifo::InvalidateResourceRecord {
                    object_id: 31,
                    flags: 0,
                    ops: Default::default(),
                },
            ],
        };
        assert!(matches!(
            runtime.resolve_standalone_invalidation(&heterogeneous),
            Ok(ReplacementResolvedInvalidation::Lifecycle(lifecycle))
                if matches!(
                    &*lifecycle,
                    reims_vgpu_core::ResolvedResourceLifecycle::ApplyValidityBatch(transitions)
                        if transitions.len() == 2
                )
        ));
        let mut payload = vec![0u8; 24];
        reims_vgpu_core::endian::st32(&mut payload[0..], task.get());
        reims_vgpu_core::endian::st32(&mut payload[4..], 2);
        for (offset, object) in [(8, 17), (16, 23)] {
            reims_vgpu_core::endian::st32(&mut payload[offset..], object);
            reims_vgpu_core::endian::st32(
                &mut payload[offset + 4..],
                crate::runtime::decode::fifo::CHILD_INVALIDATE_PAGEON_FLAGS,
            );
        }
        let admitted =
            crate::runtime::replacement_child_packet::admit_replacement_child_cpu_packet(
                &mut runtime,
                channel,
                replacement_packet(crate::model::CHILD_OP_INVALIDATE_RESOURCES, payload, 16),
            )
            .unwrap();
        let crate::runtime::replacement_child_packet::ReplacementAdmittedChildCpuPacket::ResourceLifecycle(admitted) = admitted else {
            panic!("standalone invalidation must enter the ordered lifecycle owner")
        };
        let applied = runtime.apply_admitted_resource_lifecycle(admitted).unwrap();
        assert!(matches!(
            &applied.effect,
            reims_vgpu_core::ResourceLifecycleEffect::ValidityApplied {
                guest_writes,
                gpu_reservations,
                transfers,
                states,
                ..
            } if guest_writes.len() == 1
                && guest_writes[0].0 == first.backing
                && gpu_reservations.is_empty()
                && transfers.is_empty()
                && states.len() == 1
        ));
        let published = runtime.complete_resource_lifecycle(applied, ()).unwrap();
        assert_eq!(
            published[0].completion_stamp,
            Some(reims_vgpu_core::CompletionStamp::new(channel.get(), 16))
        );

        let mut empty = vec![0u8; 8];
        reims_vgpu_core::endian::st32(&mut empty, task.get());
        let admitted =
            crate::runtime::replacement_child_packet::admit_replacement_child_cpu_packet(
                &mut runtime,
                channel,
                replacement_packet(crate::model::CHILD_OP_INVALIDATE_RESOURCES, empty, 17),
            )
            .unwrap();
        let crate::runtime::replacement_child_packet::ReplacementAdmittedChildCpuPacket::Control(
            admitted,
        ) = admitted
        else {
            panic!("an empty invalidation still owns ordered no-op completion")
        };
        let applied = runtime.apply_admitted_control(12, admitted).unwrap();
        assert!(matches!(
            applied.effect,
            ReplacementControlEffect::ContractNoOp(crate::model::CHILD_OP_INVALIDATE_RESOURCES)
        ));
        let published = runtime.complete_control(applied, ()).unwrap();
        assert_eq!(
            published[0].completion_stamp,
            Some(reims_vgpu_core::CompletionStamp::new(channel.get(), 17))
        );
    }

