        reims_vgpu_core::endian::st32(&mut payload[0..], task.get());
        reims_vgpu_core::endian::st32(
            &mut payload[4..],
            reims_vgpu_wire::ops::destroy::OPCODE_DELETE_SAMPLER_STATE,
        );
        reims_vgpu_core::endian::st32(
            &mut payload[8..],
            reims_vgpu_wire::ops::destroy::DELETE_TOTAL_LEN,
        );
